// Question bank shared by Bible Quiz, Jacob's Ladder and the quiz rounds in Bible Wars.
// To add a question, copy any line below and change it.
//   cat:   'ot' (Old Testament), 'nt' (New Testament) or 'gen' (about the Bible itself)
//   level: 1 easy, 2 medium, 3 hard, 4 expert
//          Jacob's Ladder: rungs 1-5 use level 1, rungs 6-10 level 2, rungs 11-12 level 3, rungs 13-15 level 4
//   wrong: exactly three wrong answers
//   fact:  one short sentence shown after answering
window.BIBLE_QUESTIONS = [
  // ---------- Level 1: easy ----------
  { cat: 'ot', level: 1, q: 'Who built an ark to survive the great flood?', answer: 'Noah', wrong: ['Moses', 'Abraham', 'David'], ref: 'Genesis 6:14', fact: 'God told Noah to build the ark out of gopher wood.' },
  { cat: 'ot', level: 1, q: 'On which day did God rest from creating?', answer: 'The seventh day', wrong: ['The first day', 'The third day', 'The tenth day'], ref: 'Genesis 2:2', fact: 'God made everything in six days and rested on the seventh.' },
  { cat: 'ot', level: 1, q: 'Who defeated the giant Goliath with a sling and a stone?', answer: 'David', wrong: ['Samson', 'Saul', 'Joshua'], ref: '1 Samuel 17:49', fact: 'David was a young shepherd when he faced Goliath.' },
  { cat: 'ot', level: 1, q: 'Who was swallowed by a great fish?', answer: 'Jonah', wrong: ['Elijah', 'Peter', 'Daniel'], ref: 'Jonah 1:17', fact: 'Jonah was inside the fish for three days and three nights.' },
  { cat: 'ot', level: 1, q: 'Who led the Israelites out of slavery in Egypt?', answer: 'Moses', wrong: ['Joseph', 'Aaron', 'Noah'], ref: 'Exodus 3:10', fact: 'God spoke to Moses from a burning bush and sent him to Pharaoh.' },
  { cat: 'ot', level: 1, q: 'Who was thrown into a den of lions for praying to God?', answer: 'Daniel', wrong: ['Jeremiah', 'Jonah', 'Elisha'], ref: 'Daniel 6:16', fact: 'God sent his angel to shut the lions’ mouths.' },
  { cat: 'ot', level: 1, q: 'What was the name of the first man God made?', answer: 'Adam', wrong: ['Abel', 'Noah', 'Seth'], ref: 'Genesis 2:19', fact: 'Adam gave names to all the animals.' },
  { cat: 'ot', level: 1, q: 'What did God put in the clouds as a promise after the flood?', answer: 'A rainbow', wrong: ['A star', 'A dove', 'A cloud of fire'], ref: 'Genesis 9:13', fact: 'The rainbow is a sign of God’s promise never to flood the whole earth again.' },
  { cat: 'nt', level: 1, q: 'In which town was Jesus born?', answer: 'Bethlehem', wrong: ['Nazareth', 'Jerusalem', 'Capernaum'], ref: 'Luke 2:4–7', fact: 'Bethlehem is called the city of David.' },
  { cat: 'nt', level: 1, q: 'What did Jesus turn water into at a wedding in Cana?', answer: 'Wine', wrong: ['Milk', 'Oil', 'Honey'], ref: 'John 2:9', fact: 'This was the first of Jesus’ miraculous signs in John’s Gospel.' },
  { cat: 'nt', level: 1, q: 'How many apostles did Jesus choose?', answer: 'Twelve', wrong: ['Seven', 'Ten', 'Forty'], ref: 'Mark 3:14', fact: 'Jesus chose twelve to be with him and to go out and preach.' },
  { cat: 'nt', level: 1, q: 'What was the name of Jesus’ mother?', answer: 'Mary', wrong: ['Martha', 'Elizabeth', 'Ruth'], ref: 'Luke 1:30–31', fact: 'The angel Gabriel told Mary she would have a son named Jesus.' },
  { cat: 'nt', level: 1, q: 'Which disciple walked on the water toward Jesus?', answer: 'Peter', wrong: ['John', 'Thomas', 'Andrew'], ref: 'Matthew 14:29', fact: 'Peter began to sink when he got scared, and Jesus caught him.' },
  { cat: 'gen', level: 1, q: 'What is the first book of the Bible?', answer: 'Genesis', wrong: ['Exodus', 'Matthew', 'Psalms'], ref: 'Genesis 1:1', fact: 'Genesis means “beginning”.' },
  { cat: 'gen', level: 1, q: 'What is the last book of the Bible?', answer: 'Revelation', wrong: ['Jude', 'Acts', 'Malachi'], ref: 'Revelation 1:1', fact: 'Revelation was written by John while he was on the island of Patmos.' },

  // ---------- Level 2: medium ----------
  { cat: 'ot', level: 2, q: 'Who was sold into slavery by his jealous brothers?', answer: 'Joseph', wrong: ['Benjamin', 'Isaac', 'Jacob'], ref: 'Genesis 37:28', fact: 'Joseph later became a ruler in Egypt and saved his family from famine.' },
  { cat: 'ot', level: 2, q: 'What made the walls of Jericho fall down?', answer: 'Marching, trumpets and a shout', wrong: ['An earthquake', 'Battering rams', 'A flood'], ref: 'Joshua 6:20', fact: 'The people marched around the city for seven days.' },
  { cat: 'ot', level: 2, q: 'Which strong man lost his strength when his hair was cut?', answer: 'Samson', wrong: ['Gideon', 'Goliath', 'Joab'], ref: 'Judges 16:19', fact: 'Samson was a judge of Israel.' },
  { cat: 'ot', level: 2, q: 'Which queen bravely went to the king to save her people?', answer: 'Esther', wrong: ['Jezebel', 'The Queen of Sheba', 'Vashti'], ref: 'Esther 4:16', fact: 'Esther said, “If I perish, I perish.”' },
  { cat: 'ot', level: 2, q: 'Whose wife looked back and became a pillar of salt?', answer: 'Lot’s wife', wrong: ['Noah’s wife', 'Job’s wife', 'Abraham’s wife'], ref: 'Genesis 19:26', fact: 'The angels had told the family not to look back at Sodom.' },
  { cat: 'ot', level: 2, q: 'Who prayed for a son and then gave him to serve God at the temple?', answer: 'Hannah', wrong: ['Sarah', 'Rachel', 'Deborah'], ref: '1 Samuel 1:27–28', fact: 'Hannah’s son was the prophet Samuel.' },
  { cat: 'ot', level: 2, q: 'Which king asked God for wisdom instead of riches?', answer: 'Solomon', wrong: ['David', 'Saul', 'Hezekiah'], ref: '1 Kings 3:9', fact: 'God was pleased and gave Solomon riches and honor too.' },
  { cat: 'ot', level: 2, q: 'What did Esau trade his birthright for?', answer: 'A bowl of stew', wrong: ['A coat of many colors', 'Ten camels', 'A bag of silver'], ref: 'Genesis 25:34', fact: 'Esau was hungry and traded it to his brother Jacob.' },
  { cat: 'nt', level: 2, q: 'How many loaves and fish did Jesus use to feed the 5,000?', answer: 'Five loaves and two fish', wrong: ['Two loaves and five fish', 'Seven loaves and three fish', 'Twelve loaves and one fish'], ref: 'John 6:9', fact: 'The food came from a boy’s lunch.' },
  { cat: 'nt', level: 2, q: 'Who climbed a sycamore tree to see Jesus?', answer: 'Zacchaeus', wrong: ['Nicodemus', 'Bartimaeus', 'Matthew'], ref: 'Luke 19:4', fact: 'Zacchaeus was a short tax collector from Jericho.' },
  { cat: 'nt', level: 2, q: 'Who baptized Jesus in the Jordan River?', answer: 'John the Baptist', wrong: ['Peter', 'James', 'Philip'], ref: 'Matthew 3:13', fact: 'The Spirit came down like a dove when Jesus was baptized.' },
  { cat: 'nt', level: 2, q: 'Which disciple betrayed Jesus?', answer: 'Judas Iscariot', wrong: ['Thomas', 'Simon the Zealot', 'Bartholomew'], ref: 'Matthew 26:14–15', fact: 'Judas was paid thirty pieces of silver.' },
  { cat: 'nt', level: 2, q: 'In Jesus’ story, who stopped to help the hurt traveller?', answer: 'A Samaritan', wrong: ['A priest', 'A Levite', 'A Roman soldier'], ref: 'Luke 10:33', fact: 'Jesus told the story to show who our neighbor is.' },
  { cat: 'nt', level: 2, q: 'Who said he did not know Jesus three times?', answer: 'Peter', wrong: ['John', 'Judas', 'Thomas'], ref: 'Luke 22:61', fact: 'Afterwards the rooster crowed, just as Jesus had said.' },
  { cat: 'nt', level: 2, q: 'Where was Saul going when he met the risen Jesus in a bright light?', answer: 'Damascus', wrong: ['Rome', 'Athens', 'Bethany'], ref: 'Acts 9:3', fact: 'Saul became the apostle Paul.' },

  // ---------- More level 2 ----------
  { cat: 'ot', level: 2, q: 'How many years did the Israelites wander in the wilderness?', answer: '40', wrong: ['7', '12', '70'], ref: 'Numbers 14:33', fact: 'A whole generation grew up in the desert before entering the Promised Land.' },
  { cat: 'nt', level: 2, q: 'Who wrote most of the letters in the New Testament?', answer: 'Paul', wrong: ['Peter', 'John', 'James'], ref: 'Romans 1:1', fact: 'Thirteen New Testament letters begin with Paul’s name.' },
  { cat: 'ot', level: 2, q: 'What food did God send each morning for the Israelites in the wilderness?', answer: 'Manna', wrong: ['Figs', 'Barley bread', 'Honeycomb'], ref: 'Exodus 16:15', fact: 'Manna tasted like wafers made with honey.' },
  { cat: 'ot', level: 2, q: 'Which prophetess and judge led Israel together with Barak?', answer: 'Deborah', wrong: ['Miriam', 'Huldah', 'Jael'], ref: 'Judges 4:4', fact: 'Deborah held court under a palm tree.' },
  { cat: 'ot', level: 2, q: 'Who was the first king of Israel?', answer: 'Saul', wrong: ['David', 'Samuel', 'Solomon'], ref: '1 Samuel 10:1', fact: 'The prophet Samuel anointed Saul with oil.' },
  { cat: 'gen', level: 2, q: 'Which verse is the shortest in most English Bibles?', answer: '“Jesus wept.”', wrong: ['“God is love.”', '“Fear not.”', '“Pray without ceasing.”'], ref: 'John 11:35', fact: 'Jesus wept at the tomb of his friend Lazarus.' },
  { cat: 'ot', level: 2, q: 'Who took over from Moses as the leader of Israel?', answer: 'Joshua', wrong: ['Aaron', 'Caleb', 'Gideon'], ref: 'Joshua 1:2', fact: 'God told Joshua, “Be strong and of a good courage.”' },
  { cat: 'ot', level: 2, q: 'What new name did God give Jacob after he wrestled all night?', answer: 'Israel', wrong: ['Abraham', 'Judah', 'Joseph'], ref: 'Genesis 32:28', fact: 'The twelve tribes of Israel came from Jacob’s sons.' },
  { cat: 'ot', level: 2, q: 'Which boy heard God calling his name three times in the night?', answer: 'Samuel', wrong: ['David', 'Joseph', 'Isaac'], ref: '1 Samuel 3:10', fact: 'Samuel answered, “Speak; for thy servant heareth.”' },
  { cat: 'ot', level: 2, q: 'Which prophet was fed by ravens beside a brook?', answer: 'Elijah', wrong: ['Elisha', 'Jonah', 'Jeremiah'], ref: '1 Kings 17:6', fact: 'The ravens brought him bread and meat morning and evening.' },

  // ---------- Level 3: hard ----------
  { cat: 'ot', level: 3, q: 'Who is the oldest person in the Bible, living 969 years?', answer: 'Methuselah', wrong: ['Noah', 'Adam', 'Enoch'], ref: 'Genesis 5:27', fact: 'Methuselah was Noah’s grandfather.' },
  { cat: 'ot', level: 3, q: 'Which prophet went up to heaven in a whirlwind?', answer: 'Elijah', wrong: ['Elisha', 'Isaiah', 'Ezekiel'], ref: '2 Kings 2:11', fact: 'A chariot of fire and horses of fire appeared.' },
  { cat: 'ot', level: 3, q: 'What was the name of Ruth’s mother-in-law?', answer: 'Naomi', wrong: ['Orpah', 'Leah', 'Miriam'], ref: 'Ruth 1:16', fact: 'Ruth told her, “Whither thou goest, I will go.”' },
  { cat: 'ot', level: 3, q: 'Who read the mysterious writing on the wall for King Belshazzar?', answer: 'Daniel', wrong: ['Ezra', 'Nehemiah', 'Joseph'], ref: 'Daniel 5:17', fact: 'The words were MENE, MENE, TEKEL, UPHARSIN.' },
  { cat: 'ot', level: 3, q: 'How many men did God keep in Gideon’s army?', answer: '300', wrong: ['3,000', '12', '1,000'], ref: 'Judges 7:7', fact: 'God made the army small so Israel would know he won the battle.' },
  { cat: 'ot', level: 3, q: 'Which tribe of Israel served as the priests and temple helpers?', answer: 'Levi', wrong: ['Judah', 'Benjamin', 'Dan'], ref: 'Numbers 3:6', fact: 'Moses and Aaron were from the tribe of Levi.' },
  { cat: 'ot', level: 3, q: 'In which book are the Ten Commandments first given?', answer: 'Exodus', wrong: ['Genesis', 'Leviticus', 'Numbers'], ref: 'Exodus 20', fact: 'They are repeated in Deuteronomy 5.' },
  { cat: 'nt', level: 3, q: 'In which garden did Jesus pray the night he was arrested?', answer: 'Gethsemane', wrong: ['Eden', 'Bethany', 'Golgotha'], ref: 'Matthew 26:36', fact: 'Gethsemane is near the Mount of Olives.' },
  { cat: 'nt', level: 3, q: 'Who was the first follower of Jesus to die for his faith?', answer: 'Stephen', wrong: ['James', 'Peter', 'Paul'], ref: 'Acts 7:59–60', fact: 'Stephen forgave the people who stoned him.' },
  { cat: 'nt', level: 3, q: 'What was Paul’s trade as well as preaching?', answer: 'Tentmaker', wrong: ['Fisherman', 'Carpenter', 'Tax collector'], ref: 'Acts 18:3', fact: 'He worked with Aquila and Priscilla, who were tentmakers too.' },
  { cat: 'nt', level: 3, q: 'Who did Jesus raise from the dead after four days in the tomb?', answer: 'Lazarus', wrong: ['Jairus', 'Simon', 'Nicodemus'], ref: 'John 11:17', fact: 'Lazarus was the brother of Mary and Martha.' },
  { cat: 'nt', level: 4, q: 'Who was chosen to replace Judas as an apostle?', answer: 'Matthias', wrong: ['Barnabas', 'Silas', 'Timothy'], ref: 'Acts 1:26', fact: 'The disciples cast lots, and the lot fell on Matthias.' },
  { cat: 'gen', level: 3, q: 'How many books are in most Protestant Bibles?', answer: '66', wrong: ['73', '39', '27'], ref: 'The whole Bible', fact: 'There are 39 in the Old Testament and 27 in the New.' },
  { cat: 'gen', level: 3, q: 'In what language was most of the New Testament first written?', answer: 'Greek', wrong: ['Latin', 'Hebrew', 'English'], ref: 'The New Testament', fact: 'Most of the Old Testament was written in Hebrew.' },
  { cat: 'gen', level: 3, q: 'Which book of the Bible has the most chapters?', answer: 'Psalms', wrong: ['Isaiah', 'Genesis', 'Jeremiah'], ref: 'Psalms', fact: 'Psalms has 150 chapters.' },

  // ---------- More level 3 ----------
  { cat: 'nt', level: 3, q: 'Who was the father of John the Baptist?', answer: 'Zacharias', wrong: ['Joseph', 'Simeon', 'Eli'], ref: 'Luke 1:13', fact: 'Zacharias could not speak until John was born and named.' },
  { cat: 'ot', level: 3, q: 'Which prophet married Gomer as a picture of God’s faithful love?', answer: 'Hosea', wrong: ['Amos', 'Micah', 'Joel'], ref: 'Hosea 1:3', fact: 'Hosea kept loving Gomer even when she was unfaithful.' },
  { cat: 'ot', level: 3, q: 'What was the name of Moses’ father-in-law?', answer: 'Jethro', wrong: ['Laban', 'Boaz', 'Eli'], ref: 'Exodus 3:1', fact: 'Jethro advised Moses to share the work of judging the people.' },
  { cat: 'nt', level: 3, q: 'On which island was Paul shipwrecked?', answer: 'Malta', wrong: ['Cyprus', 'Crete', 'Patmos'], ref: 'Acts 28:1', fact: 'A snake bit Paul there, and he was not harmed.' },
  { cat: 'nt', level: 3, q: 'Which high priest questioned Jesus at his trial?', answer: 'Caiaphas', wrong: ['Gamaliel', 'Nicodemus', 'Herod'], ref: 'Matthew 26:57', fact: 'The leaders gathered at Caiaphas’ house that night.' },
  { cat: 'nt', level: 3, q: 'Which disciple was called Didymus, “the twin”?', answer: 'Thomas', wrong: ['Thaddaeus', 'James', 'Andrew'], ref: 'John 11:16', fact: 'Thomas later said to the risen Jesus, “My Lord and my God.”' },
  { cat: 'ot', level: 3, q: 'Who was the mother of King Solomon?', answer: 'Bathsheba', wrong: ['Abigail', 'Michal', 'Tamar'], ref: '2 Samuel 12:24', fact: 'Bathsheba later helped make sure Solomon became king.' },
  { cat: 'ot', level: 3, q: 'How many people were saved in Noah’s ark?', answer: 'Eight', wrong: ['Two', 'Six', 'Twelve'], ref: '1 Peter 3:20', fact: 'Noah, his wife, their three sons and their sons’ wives.' },
  { cat: 'ot', level: 3, q: 'Which prophet saw a valley of dry bones come to life?', answer: 'Ezekiel', wrong: ['Jeremiah', 'Daniel', 'Isaiah'], ref: 'Ezekiel 37:1–10', fact: 'The bones came together and became a great army.' },
  { cat: 'nt', level: 3, q: 'Which Gospel writer was a doctor?', answer: 'Luke', wrong: ['Mark', 'Matthew', 'John'], ref: 'Colossians 4:14', fact: 'Paul called him “Luke, the beloved physician”. He also wrote Acts.' },

  // ---------- Deeper questions for older players ----------
  { cat: 'nt', level: 2, q: 'Which Roman governor sentenced Jesus to be crucified?', answer: 'Pontius Pilate', wrong: ['Herod Antipas', 'Felix', 'Festus'], ref: 'Matthew 27:26', fact: 'Pilate washed his hands in front of the crowd, claiming he was innocent of Jesus’ blood.' },
  { cat: 'nt', level: 2, q: 'Which of the twelve apostles had been a tax collector?', answer: 'Matthew', wrong: ['Peter', 'Andrew', 'Philip'], ref: 'Matthew 9:9', fact: 'Tax collectors were seen as traitors who worked for Rome.' },
  { cat: 'ot', level: 2, q: 'Which prophet confronted King David over his sin with Bathsheba?', answer: 'Nathan', wrong: ['Samuel', 'Elijah', 'Isaiah'], ref: '2 Samuel 12:7', fact: 'Nathan told a story about a stolen lamb, then said, “Thou art the man.”' },
  { cat: 'nt', level: 2, q: 'What does the name “Immanuel” mean?', answer: 'God with us', wrong: ['The Lord saves', 'Prince of peace', 'Son of David'], ref: 'Matthew 1:23', fact: '“The Lord saves” is the meaning of the name Jesus.' },
  { cat: 'ot', level: 2, q: 'Which empire carried the people of Judah into exile?', answer: 'Babylon', wrong: ['Assyria', 'Egypt', 'Rome'], ref: '2 Kings 25:11', fact: 'Assyria had already conquered the northern kingdom of Israel more than a century earlier.' },
  { cat: 'nt', level: 2, q: 'Which Gospel opens with “In the beginning was the Word”?', answer: 'John', wrong: ['Matthew', 'Mark', 'Luke'], ref: 'John 1:1', fact: 'John’s opening deliberately echoes Genesis 1:1.' },
  { cat: 'gen', level: 2, q: 'What does the word “gospel” mean?', answer: 'Good news', wrong: ['Holy book', 'God’s law', 'Prophecy'], ref: 'Mark 1:1', fact: 'It translates the Greek word euangelion.' },
  { cat: 'gen', level: 2, q: 'What are the first five books of the Bible often called?', answer: 'The Pentateuch', wrong: ['The Gospels', 'The Psalter', 'The Epistles'], ref: 'Genesis to Deuteronomy', fact: 'Jewish tradition calls them the Torah, meaning instruction or law.' },
  { cat: 'nt', level: 2, q: 'Which letter says that “faith without works is dead”?', answer: 'James', wrong: ['Romans', 'Hebrews', 'Galatians'], ref: 'James 2:26', fact: 'James argues that real faith shows itself in how we live.' },
  { cat: 'ot', level: 3, q: 'Which Persian king let the Jews return home and rebuild the temple?', answer: 'Cyrus', wrong: ['Nebuchadnezzar', 'Ahasuerus', 'Belshazzar'], ref: 'Ezra 1:1–3', fact: 'Isaiah named Cyrus in a prophecy long before he was born (Isaiah 44:28).' },
  { cat: 'ot', level: 3, q: 'Which Jewish feast celebrates God saving his people in the time of Esther?', answer: 'Purim', wrong: ['Passover', 'Pentecost', 'Tabernacles'], ref: 'Esther 9:26', fact: 'Purim comes from “pur”, the lot Haman cast to choose a day to destroy the Jews.' },
  { cat: 'nt', level: 3, q: 'Which respected teacher did Paul study under as a young Pharisee?', answer: 'Gamaliel', wrong: ['Caiaphas', 'Nicodemus', 'Annas'], ref: 'Acts 22:3', fact: 'Gamaliel also warned the council not to fight against God (Acts 5:39).' },
  { cat: 'nt', level: 3, q: 'Which short letter asks a Christian to welcome back his runaway slave as a brother?', answer: 'Philemon', wrong: ['Titus', 'Jude', '3 John'], ref: 'Philemon 1:16', fact: 'The slave’s name was Onesimus, which means “useful”.' },
  { cat: 'nt', level: 3, q: 'Why were the believers in Berea described as more noble?', answer: 'They searched the Scriptures daily', wrong: ['They gave all their money away', 'They prayed all night', 'They fasted every week'], ref: 'Acts 17:11', fact: 'They checked what Paul taught against the Scriptures.' },
  { cat: 'ot', level: 3, q: 'Which book begins “Vanity of vanities; all is vanity”?', answer: 'Ecclesiastes', wrong: ['Proverbs', 'Job', 'Lamentations'], ref: 'Ecclesiastes 1:2', fact: 'The writer asks what gives life meaning “under the sun”.' },
  { cat: 'nt', level: 3, q: 'Who asked Jesus, “What is truth?”', answer: 'Pontius Pilate', wrong: ['Herod', 'Caiaphas', 'Nicodemus'], ref: 'John 18:38', fact: 'Jesus had just said he came to bear witness to the truth.' },
  { cat: 'nt', level: 3, q: 'What did the Council of Jerusalem decide in Acts 15?', answer: 'Gentile believers did not have to be circumcised', wrong: ['Christians must worship on Saturday', 'Paul had to stop preaching to Gentiles', 'Only Jews could be baptized'], ref: 'Acts 15:19', fact: 'It was a turning point in welcoming non-Jews into the church.' },
  { cat: 'ot', level: 3, q: 'Which book is a long poetic struggle with why a righteous man suffers?', answer: 'Job', wrong: ['Lamentations', 'Ecclesiastes', 'Habakkuk'], ref: 'Job 1:1', fact: 'God finally answers Job out of a whirlwind.' },

  // ---------- Level 4: expert (the top of Jacob's Ladder) ----------
  { cat: 'ot', level: 4, q: 'Which giant king of Bashan slept in a bed made of iron?', answer: 'Og', wrong: ['Sihon', 'Agag', 'Goliath'], ref: 'Deuteronomy 3:11', fact: 'His bed was nine cubits long, about four meters.' },
  { cat: 'ot', level: 4, q: 'Which left-handed judge defeated Eglon, king of Moab?', answer: 'Ehud', wrong: ['Othniel', 'Shamgar', 'Jephthah'], ref: 'Judges 3:15', fact: 'Ehud hid a short sword on his right thigh.' },
  { cat: 'nt', level: 4, q: 'What was the name of the servant whose ear Peter cut off?', answer: 'Malchus', wrong: ['Onesimus', 'Cornelius', 'Barabbas'], ref: 'John 18:10', fact: 'Luke tells us Jesus touched the ear and healed him.' },
  { cat: 'gen', level: 4, q: 'How many verses are in Psalm 119, the longest chapter in the Bible?', answer: '176', wrong: ['150', '119', '200'], ref: 'Psalm 119', fact: 'It has 22 sections, one for each letter of the Hebrew alphabet.' },
  { cat: 'nt', level: 4, q: 'Which tribe of Israel was Paul from?', answer: 'Benjamin', wrong: ['Judah', 'Levi', 'Dan'], ref: 'Philippians 3:5', fact: 'Israel’s first king, Saul, was also from Benjamin.' },
  { cat: 'ot', level: 4, q: 'Which king of Judah began to reign at eight years old?', answer: 'Josiah', wrong: ['Hezekiah', 'Manasseh', 'Uzziah'], ref: '2 Kings 22:1', fact: 'In Josiah’s time the lost Book of the Law was found in the temple.' },
  { cat: 'nt', level: 4, q: 'In which city were followers of Jesus first called Christians?', answer: 'Antioch', wrong: ['Jerusalem', 'Corinth', 'Ephesus'], ref: 'Acts 11:26', fact: 'Barnabas and Paul taught there for a whole year.' },
  { cat: 'gen', level: 4, q: 'Which book of the Bible never mentions God by name?', answer: 'Esther', wrong: ['Ruth', 'Jonah', 'Obadiah'], ref: 'Esther', fact: 'Even so, the story shows God quietly protecting his people.' },
  { cat: 'ot', level: 4, q: 'King David was the great-grandson of which man?', answer: 'Boaz', wrong: ['Jesse', 'Obed', 'Judah'], ref: 'Ruth 4:21–22', fact: 'Boaz and Ruth had Obed, Obed had Jesse, and Jesse had David.' },
  // ---------- More level 1: easy ----------
  { cat: 'ot', level: 1, q: 'What was the name of the first woman?', answer: 'Eve', wrong: ['Sarah', 'Ruth', 'Leah'], ref: 'Genesis 3:20', fact: 'Adam called her Eve because she was the mother of all living.' },
  { cat: 'ot', level: 1, q: 'What did God create on the very first day?', answer: 'Light', wrong: ['Animals', 'Trees and plants', 'The sea creatures'], ref: 'Genesis 1:3', fact: 'God said, “Let there be light: and there was light.”' },
  { cat: 'ot', level: 1, q: 'In which garden did God place Adam and Eve?', answer: 'The garden of Eden', wrong: ['The garden of Gethsemane', 'The king’s garden', 'The garden of Goshen'], ref: 'Genesis 2:8', fact: 'A river went out of Eden to water the garden.' },
  { cat: 'ot', level: 1, q: 'Which creature tempted Eve to eat the forbidden fruit?', answer: 'The serpent', wrong: ['A lion', 'A raven', 'A fox'], ref: 'Genesis 3:1', fact: 'The serpent made Eve doubt what God had really said.' },
  { cat: 'ot', level: 1, q: 'Who killed his brother Abel?', answer: 'Cain', wrong: ['Seth', 'Esau', 'Lamech'], ref: 'Genesis 4:8', fact: 'God asked Cain, “Where is Abel thy brother?”' },
  { cat: 'ot', level: 1, q: 'What did the dove bring back to Noah in its beak?', answer: 'An olive leaf', wrong: ['A fig', 'A twig of cedar', 'A grape'], ref: 'Genesis 8:11', fact: 'The leaf showed Noah that the waters were going down.' },
  { cat: 'ot', level: 1, q: 'What was the name of Abraham’s wife?', answer: 'Sarah', wrong: ['Rebekah', 'Rachel', 'Leah'], ref: 'Genesis 17:15', fact: 'God changed her name from Sarai to Sarah.' },
  { cat: 'ot', level: 1, q: 'Which son did God give Abraham and Sarah when they were very old?', answer: 'Isaac', wrong: ['Ishmael', 'Jacob', 'Joseph'], ref: 'Genesis 21:2–3', fact: 'Sarah laughed for joy: God had kept his promise.' },
  { cat: 'ot', level: 1, q: 'What was the name of Jacob’s twin brother?', answer: 'Esau', wrong: ['Laban', 'Reuben', 'Ishmael'], ref: 'Genesis 25:25–26', fact: 'Jacob was born holding on to Esau’s heel.' },
  { cat: 'ot', level: 1, q: 'What special gift did Jacob give his son Joseph?', answer: 'A coat of many colours', wrong: ['A gold ring', 'A shepherd’s staff', 'A silver cup'], ref: 'Genesis 37:3', fact: 'The coat showed Joseph was his father’s favourite, and his brothers grew jealous.' },
  { cat: 'ot', level: 1, q: 'Where was baby Moses hidden to keep him safe?', answer: 'In a basket among the reeds', wrong: ['In a cave', 'Down a well', 'Under a haystack'], ref: 'Exodus 2:3', fact: 'Pharaoh’s daughter found him and raised him as her own son.' },
  { cat: 'ot', level: 1, q: 'From what did God speak to Moses in the desert?', answer: 'A burning bush', wrong: ['A talking donkey', 'A pillar of salt', 'A rushing river'], ref: 'Exodus 3:2', fact: 'The bush was on fire, but it did not burn up.' },
  { cat: 'ot', level: 1, q: 'Which sea did God part so Israel could cross on dry ground?', answer: 'The Red Sea', wrong: ['The Dead Sea', 'The Sea of Galilee', 'The Great Sea'], ref: 'Exodus 14:21', fact: 'God sent a strong east wind all night to push the waters back.' },
  { cat: 'ot', level: 1, q: 'How many commandments did God write on the tablets of stone?', answer: 'Ten', wrong: ['Seven', 'Twelve', 'Forty'], ref: 'Exodus 34:28', fact: 'Jesus summed them up as loving God and loving your neighbour.' },
  { cat: 'ot', level: 1, q: 'What job did young David do before he became king?', answer: 'He looked after sheep', wrong: ['He caught fish', 'He made tents', 'He baked bread'], ref: '1 Samuel 16:11', fact: 'David was out with the sheep when Samuel came to anoint him.' },
  { cat: 'ot', level: 1, q: 'Which instrument did David play to calm King Saul?', answer: 'The harp', wrong: ['The trumpet', 'The drum', 'The flute'], ref: '1 Samuel 16:23', fact: 'When David played, Saul was refreshed.' },
  { cat: 'ot', level: 1, q: 'Which three friends were thrown into a fiery furnace?', answer: 'Shadrach, Meshach and Abednego', wrong: ['Peter, James and John', 'Moses, Aaron and Hur', 'Ezra, Nehemiah and Haggai'], ref: 'Daniel 3:20–25', fact: 'The king saw a fourth person walking with them in the fire.' },
  { cat: 'ot', level: 1, q: 'Finish the verse: “The LORD is my ...; I shall not want.”', answer: 'shepherd', wrong: ['king', 'rock', 'light'], ref: 'Psalm 23:1', fact: 'Jesus later said, “I am the good shepherd.”' },
  { cat: 'ot', level: 1, q: 'On which day did God make people?', answer: 'The sixth day', wrong: ['The first day', 'The fourth day', 'The seventh day'], ref: 'Genesis 1:27, 31', fact: 'God made people in his own image.' },
  { cat: 'ot', level: 1, q: 'What did God use to form the first man?', answer: 'The dust of the ground', wrong: ['A rib', 'Water from a river', 'A branch from a tree'], ref: 'Genesis 2:7', fact: 'God breathed into him the breath of life.' },
  { cat: 'ot', level: 1, q: 'From what did God make Eve?', answer: 'One of Adam’s ribs', wrong: ['The dust of the ground', 'A cloud', 'Clay from a riverbank'], ref: 'Genesis 2:22', fact: 'God brought Eve to Adam, and he was full of joy.' },
  { cat: 'ot', level: 1, q: 'Who was Moses’ brother who spoke for him before Pharaoh?', answer: 'Aaron', wrong: ['Joshua', 'Caleb', 'Levi'], ref: 'Exodus 4:14', fact: 'Aaron later became the first high priest of Israel.' },
  { cat: 'ot', level: 1, q: 'How many plagues did God send on Egypt?', answer: 'Ten', wrong: ['Three', 'Seven', 'Twelve'], ref: 'Exodus 7–12', fact: 'After the last plague, Pharaoh finally let the people go.' },
  { cat: 'ot', level: 1, q: 'God told Abraham his descendants would be as many as what?', answer: 'The stars in the sky', wrong: ['The trees in the forest', 'The fish in the sea', 'The hills in the land'], ref: 'Genesis 15:5', fact: 'Abraham believed God, and it was counted to him for righteousness.' },
  { cat: 'ot', level: 1, q: 'What did Jacob see in his dream at Bethel?', answer: 'A ladder reaching up to heaven', wrong: ['A burning bush', 'A chariot of fire', 'A great golden statue'], ref: 'Genesis 28:12', fact: 'Angels were going up and down on it. Jesus spoke of this in John 1:51.' },
  { cat: 'ot', level: 1, q: 'Which wise king built the first temple in Jerusalem?', answer: 'Solomon', wrong: ['David', 'Saul', 'Josiah'], ref: '1 Kings 6:1', fact: 'David wanted to build it, but God chose his son Solomon.' },
  { cat: 'ot', level: 1, q: 'What did God send down from heaven when Elijah prayed on Mount Carmel?', answer: 'Fire', wrong: ['Manna', 'Hailstones', 'A flock of quails'], ref: '1 Kings 18:38', fact: 'The fire burned up the sacrifice, the wood, the stones and even the water.' },
  { cat: 'ot', level: 1, q: 'Which giant did David fight?', answer: 'Goliath', wrong: ['Og', 'Samson', 'Nimrod'], ref: '1 Samuel 17:4', fact: 'David said the battle belonged to the Lord.' },
  { cat: 'ot', level: 1, q: 'What did God use to lead Israel through the desert by day?', answer: 'A pillar of cloud', wrong: ['A bright star', 'A flock of birds', 'A golden calf'], ref: 'Exodus 13:21', fact: 'By night God led them with a pillar of fire.' },
  { cat: 'ot', level: 1, q: 'What did God ask Noah to build?', answer: 'An ark', wrong: ['A temple', 'A tower', 'A city wall'], ref: 'Genesis 6:14', fact: 'Noah did everything just as God commanded him.' },
  { cat: 'ot', level: 1, q: 'What did Jonah do right after God told him to go to Nineveh?', answer: 'He ran away on a ship', wrong: ['He went straight there', 'He hid in a cave', 'He climbed a mountain'], ref: 'Jonah 1:3', fact: 'You cannot run from God, but God never stopped caring for Jonah.' },
  { cat: 'ot', level: 1, q: 'Which son of Adam and Eve looked after sheep?', answer: 'Abel', wrong: ['Cain', 'Seth', 'Enoch'], ref: 'Genesis 4:2', fact: 'Cain worked the ground, and Abel was a keeper of sheep.' },

  { cat: 'nt', level: 1, q: 'Where did Mary lay baby Jesus after he was born?', answer: 'In a manger', wrong: ['In a basket', 'In a wooden cradle', 'In a bed at the inn'], ref: 'Luke 2:7', fact: 'There was no room for them in the inn.' },
  { cat: 'nt', level: 1, q: 'Who followed a star to find the young Jesus?', answer: 'Wise men from the east', wrong: ['Shepherds', 'Roman soldiers', 'Temple priests'], ref: 'Matthew 2:1–2', fact: 'They came to worship the one born King of the Jews.' },
  { cat: 'nt', level: 1, q: 'Which gifts did the wise men bring to Jesus?', answer: 'Gold, frankincense and myrrh', wrong: ['Gold, silver and bronze', 'Bread, wine and oil', 'Silk, spices and ivory'], ref: 'Matthew 2:11', fact: 'They fell down and worshipped him first, then opened their treasures.' },
  { cat: 'nt', level: 1, q: 'Who told the shepherds that Jesus had been born?', answer: 'An angel', wrong: ['A prophet', 'King Herod', 'The wise men'], ref: 'Luke 2:9–11', fact: 'The angel said, “Unto you is born this day ... a Saviour, which is Christ the Lord.”' },
  { cat: 'nt', level: 1, q: 'What was the name of Mary’s husband?', answer: 'Joseph', wrong: ['Zacharias', 'Simeon', 'Nicodemus'], ref: 'Matthew 1:24', fact: 'An angel told Joseph in a dream to take Mary as his wife.' },
  { cat: 'nt', level: 1, q: 'What was Joseph’s trade, the work Jesus grew up around?', answer: 'Carpenter', wrong: ['Fisherman', 'Shepherd', 'Tentmaker'], ref: 'Matthew 13:55', fact: 'People in his home town asked, “Is not this the carpenter’s son?”' },
  { cat: 'nt', level: 1, q: 'In which town did Jesus grow up?', answer: 'Nazareth', wrong: ['Bethlehem', 'Jericho', 'Capernaum'], ref: 'Luke 2:51', fact: 'That is why people called him Jesus of Nazareth.' },
  { cat: 'nt', level: 1, q: 'What work did Peter and Andrew do before following Jesus?', answer: 'They were fishermen', wrong: ['They were tax collectors', 'They were farmers', 'They were soldiers'], ref: 'Matthew 4:18–19', fact: 'Jesus said, “Follow me, and I will make you fishers of men.”' },
  { cat: 'nt', level: 1, q: 'On which day did Jesus rise from the dead?', answer: 'The third day', wrong: ['The first day', 'The seventh day', 'The fortieth day'], ref: '1 Corinthians 15:4', fact: 'The empty tomb is the best news ever told.' },
  { cat: 'nt', level: 1, q: 'Which prayer begins “Our Father which art in heaven”?', answer: 'The Lord’s Prayer', wrong: ['The Song of Moses', 'Psalm 23', 'Hannah’s prayer'], ref: 'Matthew 6:9', fact: 'Jesus taught it when his disciples asked him how to pray.' },
  { cat: 'nt', level: 1, q: 'When Jesus said “Peace, be still,” what obeyed him?', answer: 'The wind and the waves', wrong: ['A crowd of people', 'A herd of pigs', 'A pack of wolves'], ref: 'Mark 4:39', fact: 'The disciples asked, “What manner of man is this?”' },
  { cat: 'nt', level: 1, q: 'Who did the disciples try to keep away, until Jesus told them to let them come?', answer: 'Little children', wrong: ['Tax collectors', 'Roman soldiers', 'Pharisees'], ref: 'Mark 10:14', fact: 'Jesus took them in his arms and blessed them.' },
  { cat: 'nt', level: 1, q: 'In Jesus’ story, the shepherd left 99 sheep to look for what?', answer: 'One lost sheep', wrong: ['A lost coin', 'A lost son', 'A lost lamp'], ref: 'Luke 15:4', fact: 'Jesus said heaven rejoices over one sinner who comes home.' },
  { cat: 'nt', level: 1, q: 'What did the father do when his lost son came home?', answer: 'Ran to him, hugged him and kissed him', wrong: ['Sent him away', 'Made him a servant', 'Told him to wait at the gate'], ref: 'Luke 15:20', fact: 'The story shows how God welcomes anyone who turns back to him.' },
  { cat: 'nt', level: 1, q: 'What did Jesus ride into Jerusalem before Passover?', answer: 'A young donkey', wrong: ['A white horse', 'A camel', 'A chariot'], ref: 'John 12:14', fact: 'He came as a humble king, just as Zechariah had foretold.' },
  { cat: 'nt', level: 1, q: 'What did Jesus share with his disciples at the Last Supper?', answer: 'Bread and the cup', wrong: ['Fish and honey', 'Lamb and figs', 'Milk and dates'], ref: 'Luke 22:19–20', fact: 'He said, “This do in remembrance of me.”' },
  { cat: 'nt', level: 1, q: 'Which disciple said he would not believe until he saw the nail marks?', answer: 'Thomas', wrong: ['Peter', 'Andrew', 'Philip'], ref: 'John 20:25', fact: 'Jesus showed him his hands, and Thomas believed.' },
  { cat: 'nt', level: 1, q: 'Who came upon the disciples on the day of Pentecost?', answer: 'The Holy Spirit', wrong: ['The angel Gabriel', 'Moses and Elijah', 'A choir of angels'], ref: 'Acts 2:4', fact: 'They began to speak in other languages about God’s wonderful works.' },
  { cat: 'nt', level: 1, q: 'Finish the verse: “For God so loved the ..., that he gave his only begotten Son.”', answer: 'world', wrong: ['church', 'children', 'angels'], ref: 'John 3:16', fact: 'Whoever believes in him should not perish, but have everlasting life.' },
  { cat: 'nt', level: 1, q: 'Jesus said, “I am the good ...”', answer: 'shepherd', wrong: ['king', 'teacher', 'farmer'], ref: 'John 10:11', fact: 'The good shepherd gives his life for the sheep.' },
  { cat: 'nt', level: 1, q: 'Jesus said, “I am the bread of ...”', answer: 'life', wrong: ['heaven', 'peace', 'joy'], ref: 'John 6:35', fact: 'He said whoever comes to him will never hunger.' },
  { cat: 'nt', level: 1, q: 'Jesus said, “I am the way, the truth, and the ...”', answer: 'life', wrong: ['light', 'door', 'vine'], ref: 'John 14:6', fact: 'He added, “No man cometh unto the Father, but by me.”' },
  { cat: 'nt', level: 1, q: 'Where did Mary and Joseph find twelve-year-old Jesus after three days of searching?', answer: 'In the temple', wrong: ['At the market', 'By the river', 'At a friend’s house'], ref: 'Luke 2:46', fact: 'He was listening to the teachers and asking them questions.' },
  { cat: 'nt', level: 1, q: 'How many days did Jesus fast in the wilderness?', answer: '40', wrong: ['3', '7', '12'], ref: 'Matthew 4:2', fact: 'He answered every temptation with words from Scripture.' },
  { cat: 'nt', level: 1, q: 'Who tempted Jesus in the wilderness?', answer: 'The devil', wrong: ['King Herod', 'The Pharisees', 'Judas'], ref: 'Matthew 4:1', fact: 'Jesus answered him, “It is written.”' },
  { cat: 'nt', level: 1, q: 'Jesus said the second great commandment is to love whom as yourself?', answer: 'Your neighbour', wrong: ['Your king', 'Your teacher', 'Only your family'], ref: 'Matthew 22:39', fact: 'The first is to love God with all your heart, soul and mind.' },
  { cat: 'nt', level: 1, q: 'Jesus told his followers, “Ye are the ... of the earth.”', answer: 'salt', wrong: ['bread', 'gold', 'rock'], ref: 'Matthew 5:13', fact: 'Salt brings out flavour, and so should our lives.' },
  { cat: 'nt', level: 1, q: 'In Jesus’ story, where did the wise man build his house?', answer: 'On the rock', wrong: ['On the sand', 'By the river', 'On a hilltop of grass'], ref: 'Matthew 7:24', fact: 'The wise man hears Jesus’ words and does them.' },
  { cat: 'nt', level: 1, q: 'What happened to the house built on the sand when the storm came?', answer: 'It fell', wrong: ['It floated away safely', 'It stood firm', 'It caught fire'], ref: 'Matthew 7:27', fact: 'Hearing without doing is like building on sand.' },
  { cat: 'nt', level: 1, q: 'What did Jesus heal the ten men of?', answer: 'Leprosy', wrong: ['Blindness', 'Deafness', 'Fever'], ref: 'Luke 17:12–14', fact: 'Only one came back to say thank you.' },
  { cat: 'nt', level: 1, q: 'Who was Jesus’ cousin who prepared the way for him?', answer: 'John the Baptist', wrong: ['John the apostle', 'James', 'Lazarus'], ref: 'Mark 1:4–7', fact: 'John said someone mightier than him was coming.' },
  { cat: 'nt', level: 1, q: 'Which angel told Mary she would have a baby?', answer: 'Gabriel', wrong: ['Michael', 'Raphael', 'Lucifer'], ref: 'Luke 1:26–27', fact: 'Gabriel said, “With God nothing shall be impossible.”' },
  { cat: 'nt', level: 1, q: 'What sound did Peter hear after denying Jesus three times?', answer: 'A rooster crowing', wrong: ['A trumpet', 'Thunder', 'A dog barking'], ref: 'Matthew 26:74–75', fact: 'Jesus later restored Peter by the sea and gave him a fresh start.' },
  { cat: 'nt', level: 1, q: 'What did Jesus wash at the Last Supper?', answer: 'His disciples’ feet', wrong: ['The cups and plates', 'The disciples’ hands', 'The table'], ref: 'John 13:5', fact: 'Jesus, their Lord, showed them how to serve one another.' },
  { cat: 'nt', level: 1, q: 'Finish the verse: “I can do all things through ... which strengtheneth me.”', answer: 'Christ', wrong: ['faith', 'prayer', 'wisdom'], ref: 'Philippians 4:13', fact: 'Paul wrote this while in prison, having learned to be content.' },
  { cat: 'nt', level: 1, q: 'What did Jesus call himself in John 8:12?', answer: 'The light of the world', wrong: ['The king of Rome', 'The salt of the earth', 'The rock of ages'], ref: 'John 8:12', fact: 'Whoever follows him will not walk in darkness.' },
  { cat: 'nt', level: 1, q: 'Where was Jesus put after he died on the cross?', answer: 'In a tomb cut out of rock', wrong: ['In a field', 'In the temple', 'In a palace'], ref: 'Mark 15:46', fact: 'A great stone was rolled against the door. It did not stay shut.' },
  { cat: 'nt', level: 1, q: 'Who healed people, calmed storms and forgave sins in the Gospels?', answer: 'Jesus', wrong: ['Moses', 'Elijah', 'Paul'], ref: 'Mark 2:5–12', fact: 'He healed a man to show he had power to forgive sins.' },

  { cat: 'gen', level: 1, q: 'What is the first book of the New Testament?', answer: 'Matthew', wrong: ['Mark', 'Acts', 'Romans'], ref: 'Matthew 1:1', fact: 'Matthew opens with the family line of Jesus.' },
  { cat: 'gen', level: 1, q: 'Which of these is NOT one of the four Gospels?', answer: 'Acts', wrong: ['Matthew', 'Mark', 'John'], ref: 'Acts 1:1', fact: 'Acts tells what happened after Jesus went back to heaven.' },
  { cat: 'gen', level: 1, q: 'What are the two main parts of the Bible called?', answer: 'The Old Testament and the New Testament', wrong: ['The Law and the Psalms', 'The Gospels and the Letters', 'The Prophets and the Kings'], ref: 'The whole Bible', fact: 'The Old looks forward to Jesus; the New tells of his coming.' },
  { cat: 'gen', level: 1, q: 'Which book of the Bible is full of songs and prayers?', answer: 'Psalms', wrong: ['Leviticus', 'Numbers', 'Acts'], ref: 'Psalm 150:6', fact: 'It ends, “Let every thing that hath breath praise the LORD.”' },
  { cat: 'gen', level: 1, q: 'Which book is full of short wise sayings?', answer: 'Proverbs', wrong: ['Exodus', 'Judges', 'Revelation'], ref: 'Proverbs 1:1', fact: 'It begins with the proverbs of Solomon, son of David.' },
  { cat: 'gen', level: 1, q: 'Which book comes right after Genesis?', answer: 'Exodus', wrong: ['Leviticus', 'Deuteronomy', 'Joshua'], ref: 'Exodus 1:1', fact: 'Exodus means “going out”, as Israel left Egypt.' },
  { cat: 'gen', level: 1, q: 'How many Gospels are there in the New Testament?', answer: 'Four', wrong: ['Two', 'Three', 'Twelve'], ref: 'Matthew, Mark, Luke and John', fact: 'Each tells the story of Jesus from a different angle.' },
  { cat: 'gen', level: 1, q: 'Which shepherd king wrote many of the Psalms?', answer: 'David', wrong: ['Solomon', 'Saul', 'Moses'], ref: 'Psalm 23', fact: 'Many psalms are titled “A Psalm of David”.' },
  { cat: 'gen', level: 1, q: 'Where in the Bible is the famous verse “For God so loved the world”?', answer: 'John 3:16', wrong: ['Genesis 1:1', 'Psalm 23:1', 'Romans 8:28'], ref: 'John 3:16', fact: 'Jesus spoke these words to Nicodemus.' },
  { cat: 'gen', level: 1, q: 'Which Psalm begins “The LORD is my shepherd”?', answer: 'Psalm 23', wrong: ['Psalm 1', 'Psalm 100', 'Psalm 150'], ref: 'Psalm 23:1', fact: 'It is one of the best-loved passages in the whole Bible.' },
  { cat: 'gen', level: 1, q: 'Which book tells how the church grew after Jesus went back to heaven?', answer: 'Acts', wrong: ['Romans', 'Genesis', 'Hebrews'], ref: 'Acts 1:8', fact: 'Jesus said the good news would go to the ends of the earth.' },
  { cat: 'gen', level: 1, q: 'How many letters to the Corinthians are in the New Testament?', answer: 'Two', wrong: ['One', 'Three', 'Four'], ref: '1 and 2 Corinthians', fact: 'Paul wrote both to the church in Corinth.' },
  { cat: 'gen', level: 1, q: 'In which part of the Bible do we read about Jesus’ life on earth?', answer: 'The Gospels', wrong: ['The Law', 'The Psalms', 'The Prophets'], ref: 'Mark 1:1', fact: 'Mark begins, “The beginning of the gospel of Jesus Christ.”' },
  { cat: 'gen', level: 1, q: 'Which book comes right after Psalms?', answer: 'Proverbs', wrong: ['Ecclesiastes', 'Job', 'Isaiah'], ref: 'Proverbs 1:7', fact: '“The fear of the LORD is the beginning of knowledge.”' },
  { cat: 'gen', level: 1, q: 'In which Testament do we read the stories of Moses and David?', answer: 'The Old Testament', wrong: ['The New Testament', 'The Gospels', 'The book of Acts'], ref: 'Exodus 3; 1 Samuel 16', fact: 'Both lived long before Jesus, and David was his ancestor.' },
  { cat: 'gen', level: 1, q: 'In which Testament do we read about Jesus’ birth?', answer: 'The New Testament', wrong: ['The Old Testament', 'The Law', 'The Psalms'], ref: 'Luke 2', fact: 'The Old Testament promised he would come; the New tells how he came.' },

  // ---------- More level 2: medium ----------
  { cat: 'ot', level: 2, q: 'On which mountain did Moses receive the Ten Commandments?', answer: 'Mount Sinai', wrong: ['Mount Carmel', 'Mount Ararat', 'Mount of Olives'], ref: 'Exodus 19:20', fact: 'The mountain shook and was covered in smoke as God came down.' },
  { cat: 'ot', level: 2, q: 'Who was David’s best friend and the son of King Saul?', answer: 'Jonathan', wrong: ['Absalom', 'Joab', 'Abner'], ref: '1 Samuel 18:1', fact: 'Jonathan loved David as his own soul.' },
  { cat: 'ot', level: 2, q: 'On which mountain did Noah’s ark come to rest?', answer: 'The mountains of Ararat', wrong: ['Mount Sinai', 'Mount Zion', 'Mount Hermon'], ref: 'Genesis 8:4', fact: 'The ark rested there in the seventh month.' },
  { cat: 'ot', level: 2, q: 'Which tree’s fruit did God tell Adam not to eat?', answer: 'The tree of the knowledge of good and evil', wrong: ['The tree of life', 'The fig tree', 'The olive tree'], ref: 'Genesis 2:17', fact: 'Jesus came to undo what went wrong in that garden.' },
  { cat: 'ot', level: 2, q: 'Whose dreams about fat and thin cows did Joseph explain?', answer: 'Pharaoh’s', wrong: ['Potiphar’s', 'Jacob’s', 'Nebuchadnezzar’s'], ref: 'Genesis 41:25–27', fact: 'The dreams warned of seven good years and seven years of famine.' },
  { cat: 'ot', level: 2, q: 'Which sister of Moses led the women in song with a timbrel?', answer: 'Miriam', wrong: ['Zipporah', 'Deborah', 'Jochebed'], ref: 'Exodus 15:20', fact: 'They sang after God brought them safely through the sea.' },
  { cat: 'ot', level: 2, q: 'What was the last of the ten plagues on Egypt?', answer: 'The death of the firstborn', wrong: ['Darkness', 'Frogs', 'Hail'], ref: 'Exodus 12:29', fact: 'Homes marked with lamb’s blood were passed over, a picture of Jesus, our Passover lamb.' },
  { cat: 'ot', level: 2, q: 'For which nation did Goliath fight?', answer: 'The Philistines', wrong: ['The Egyptians', 'The Amalekites', 'The Moabites'], ref: '1 Samuel 17:4', fact: 'Goliath came from the city of Gath.' },
  { cat: 'ot', level: 2, q: 'How many smooth stones did David pick from the brook?', answer: 'Five', wrong: ['One', 'Three', 'Seven'], ref: '1 Samuel 17:40', fact: 'He only needed one.' },
  { cat: 'ot', level: 2, q: 'Which king had Daniel thrown into the lions’ den?', answer: 'Darius', wrong: ['Nebuchadnezzar', 'Cyrus', 'Belshazzar'], ref: 'Daniel 6:16', fact: 'Darius hoped Daniel’s God would save him, and he did.' },
  { cat: 'ot', level: 2, q: 'Who was the father of King David?', answer: 'Jesse', wrong: ['Obed', 'Boaz', 'Saul'], ref: '1 Samuel 16:1', fact: 'Isaiah foretold a branch from the root of Jesse: Jesus.' },
  { cat: 'ot', level: 2, q: 'Why did the building of the tower of Babel stop?', answer: 'God mixed up their language', wrong: ['A flood washed it away', 'They ran out of bricks', 'An earthquake knocked it down'], ref: 'Genesis 11:7–9', fact: 'Babel sounds like the Hebrew word for confusion.' },
  { cat: 'ot', level: 2, q: 'Who “walked with God” and was taken by God without dying?', answer: 'Enoch', wrong: ['Methuselah', 'Lamech', 'Seth'], ref: 'Genesis 5:24', fact: 'Hebrews 11 says Enoch pleased God.' },
  { cat: 'ot', level: 2, q: 'What did God provide for Abraham to sacrifice in Isaac’s place?', answer: 'A ram caught in a thicket', wrong: ['A spotless lamb from his flock', 'A young bull', 'Two doves'], ref: 'Genesis 22:13', fact: 'It points to Jesus, given in our place.' },
  { cat: 'ot', level: 2, q: 'Who became the wife of Isaac?', answer: 'Rebekah', wrong: ['Rachel', 'Leah', 'Hagar'], ref: 'Genesis 24:67', fact: 'Abraham’s servant met her at a well, where she watered his camels.' },
  { cat: 'ot', level: 2, q: 'Which of Laban’s daughters did Jacob love most?', answer: 'Rachel', wrong: ['Leah', 'Dinah', 'Zilpah'], ref: 'Genesis 29:18', fact: 'Jacob’s years of work seemed like only a few days because of his love.' },
  { cat: 'ot', level: 2, q: 'Who was the youngest of Jacob’s twelve sons?', answer: 'Benjamin', wrong: ['Joseph', 'Judah', 'Reuben'], ref: 'Genesis 35:18', fact: 'Rachel died giving birth to him.' },
  { cat: 'ot', level: 2, q: 'What did Aaron make while Moses was up on the mountain?', answer: 'A golden calf', wrong: ['A bronze snake', 'A silver altar', 'A wooden ark'], ref: 'Exodus 32:4', fact: 'The people turned to an idol only weeks after God rescued them.' },
  { cat: 'ot', level: 2, q: 'Whose donkey spoke to him on the road?', answer: 'Balaam’s', wrong: ['Abraham’s', 'Saul’s', 'Gideon’s'], ref: 'Numbers 22:28', fact: 'The donkey saw the angel before Balaam did.' },
  { cat: 'ot', level: 2, q: 'Which two of the twelve spies trusted God could give them the land?', answer: 'Joshua and Caleb', wrong: ['Moses and Aaron', 'Gideon and Barak', 'Eldad and Medad'], ref: 'Numbers 14:6–9', fact: 'They were the only adults of that generation to enter the land.' },
  { cat: 'ot', level: 2, q: 'How did Gideon test God’s promise using a fleece of wool?', answer: 'He asked for dew on the fleece but not the ground', wrong: ['He asked for it to catch fire', 'He asked for it to turn red', 'He asked for it to float on water'], ref: 'Judges 6:37', fact: 'The next night he asked for the opposite, and God answered again.' },
  { cat: 'ot', level: 2, q: 'Who tricked Samson into telling the secret of his strength?', answer: 'Delilah', wrong: ['Jezebel', 'Rahab', 'Jael'], ref: 'Judges 16:6', fact: 'She was paid silver by the Philistine lords.' },
  { cat: 'ot', level: 2, q: 'Which queen travelled far to test Solomon with hard questions?', answer: 'The Queen of Sheba', wrong: ['Queen Esther', 'Queen Vashti', 'Queen Jezebel'], ref: '1 Kings 10:1', fact: 'Jesus said “a greater than Solomon is here,” speaking of himself.' },
  { cat: 'ot', level: 2, q: 'In which river did Naaman wash seven times to be healed?', answer: 'The Jordan', wrong: ['The Nile', 'The Euphrates', 'The Abana'], ref: '2 Kings 5:14', fact: 'His skin became like the skin of a little child.' },
  { cat: 'ot', level: 2, q: 'Who was the cousin who raised Esther?', answer: 'Mordecai', wrong: ['Haman', 'Nehemiah', 'Ezra'], ref: 'Esther 2:7', fact: 'Mordecai asked, “Who knoweth whether thou art come to the kingdom for such a time as this?”' },
  { cat: 'ot', level: 2, q: 'Who plotted to destroy all the Jews in Esther’s time?', answer: 'Haman', wrong: ['Mordecai', 'Ahasuerus', 'Sanballat'], ref: 'Esther 3:6', fact: 'Haman was hanged on the gallows he had built for Mordecai.' },
  { cat: 'ot', level: 2, q: 'To which great city did God send Jonah to preach?', answer: 'Nineveh', wrong: ['Babylon', 'Tyre', 'Damascus'], ref: 'Jonah 1:2', fact: 'The whole city turned from evil, and God showed mercy.' },
  { cat: 'ot', level: 2, q: 'Which prophet followed Elijah and received his cloak?', answer: 'Elisha', wrong: ['Gehazi', 'Obadiah', 'Micaiah'], ref: '2 Kings 2:13', fact: 'Elisha struck the Jordan with the cloak and the waters parted.' },
  { cat: 'ot', level: 2, q: 'Which young woman from Moab chose to follow Naomi’s God?', answer: 'Ruth', wrong: ['Orpah', 'Rahab', 'Abigail'], ref: 'Ruth 1:16', fact: 'She became an ancestor of King David and of Jesus.' },
  { cat: 'ot', level: 2, q: 'What did Joseph’s brothers do with his coat after selling him?', answer: 'Dipped it in goat’s blood', wrong: ['Burned it', 'Sold it at the market', 'Buried it in the sand'], ref: 'Genesis 37:31', fact: 'Jacob thought a wild animal had killed Joseph.' },
  { cat: 'ot', level: 2, q: 'Who hid the two spies on her roof in Jericho?', answer: 'Rahab', wrong: ['Deborah', 'Ruth', 'Miriam'], ref: 'Joshua 2:6', fact: 'Rahab is named in Jesus’ family line in Matthew 1:5.' },
  { cat: 'ot', level: 2, q: 'Which prophet anointed young David as king?', answer: 'Samuel', wrong: ['Nathan', 'Elijah', 'Gad'], ref: '1 Samuel 16:13', fact: 'God told Samuel, “The LORD looketh on the heart.”' },
  { cat: 'ot', level: 2, q: 'Which son of David rebelled and tried to take his father’s throne?', answer: 'Absalom', wrong: ['Solomon', 'Jonathan', 'Amnon'], ref: '2 Samuel 15:10', fact: 'David still wept for him: “O my son Absalom.”' },
  { cat: 'ot', level: 2, q: 'Which wicked queen threatened Elijah’s life?', answer: 'Jezebel', wrong: ['Athaliah', 'Vashti', 'Michal'], ref: '1 Kings 19:2', fact: 'Elijah ran, but God met him gently with food and rest.' },
  { cat: 'ot', level: 2, q: 'What did God tell Moses to do to the rock at Horeb to get water?', answer: 'Strike it', wrong: ['Pour oil on it', 'Pray over it seven times', 'Break it with an axe'], ref: 'Exodus 17:6', fact: 'Paul wrote, “that Rock was Christ” (1 Corinthians 10:4).' },
  { cat: 'ot', level: 2, q: 'Who had a dream of a huge statue made of gold, silver, brass, iron and clay?', answer: 'Nebuchadnezzar', wrong: ['Pharaoh', 'Darius', 'Cyrus'], ref: 'Daniel 2:31–33', fact: 'A stone cut without hands broke it and became a great mountain.' },
  { cat: 'ot', level: 2, q: 'How long did it rain during the flood?', answer: '40 days and 40 nights', wrong: ['7 days and 7 nights', '12 days', 'A whole year'], ref: 'Genesis 7:12', fact: 'Noah was in the ark much longer than that while the waters went down.' },
  { cat: 'ot', level: 2, q: 'Which prophet saw the Lord “high and lifted up” in the temple?', answer: 'Isaiah', wrong: ['Jeremiah', 'Amos', 'Hosea'], ref: 'Isaiah 6:1', fact: 'Isaiah answered God, “Here am I; send me.”' },
  { cat: 'ot', level: 2, q: 'Which young prophet said, “I am a child,” when God called him?', answer: 'Jeremiah', wrong: ['Samuel', 'Daniel', 'Joel'], ref: 'Jeremiah 1:6', fact: 'God said, “Be not afraid of their faces: for I am with thee.”' },
  { cat: 'ot', level: 2, q: 'Who led the rebuilding of Jerusalem’s walls after the exile?', answer: 'Nehemiah', wrong: ['Ezra', 'Zerubbabel', 'Haggai'], ref: 'Nehemiah 2:17', fact: 'He prayed first, then worked hard with the people.' },
  { cat: 'ot', level: 2, q: 'Which man was described as perfect and upright, yet lost everything he had?', answer: 'Job', wrong: ['Joseph', 'Jonah', 'Jacob'], ref: 'Job 1:1, 1:21', fact: 'Job said, “The LORD gave, and the LORD hath taken away; blessed be the name of the LORD.”' },

  { cat: 'nt', level: 2, q: 'Where did Jesus meet the Samaritan woman?', answer: 'At Jacob’s well', wrong: ['At the pool of Siloam', 'By the Jordan River', 'At the temple gate'], ref: 'John 4:6–7', fact: 'Jesus offered her “living water”.' },
  { cat: 'nt', level: 2, q: 'What did Jesus tell Nicodemus a person must be to see the kingdom of God?', answer: 'Born again', wrong: ['Baptized in the Jordan', 'A son of Abraham', 'Perfect in the law'], ref: 'John 3:3', fact: 'Nicodemus came to Jesus by night.' },
  { cat: 'nt', level: 2, q: 'Which two Old Testament figures appeared with Jesus at the Transfiguration?', answer: 'Moses and Elijah', wrong: ['Abraham and David', 'Noah and Enoch', 'Isaiah and Jeremiah'], ref: 'Matthew 17:3', fact: 'A voice said, “This is my beloved Son ... hear ye him.”' },
  { cat: 'nt', level: 2, q: 'Who answered Jesus, “Thou art the Christ, the Son of the living God”?', answer: 'Peter', wrong: ['John', 'Nathanael', 'Martha'], ref: 'Matthew 16:16', fact: 'Jesus said God the Father had shown this to Peter.' },
  { cat: 'nt', level: 2, q: 'Who was Simon Peter’s brother, also a disciple?', answer: 'Andrew', wrong: ['James', 'Philip', 'Matthew'], ref: 'John 1:40–41', fact: 'Andrew brought Peter to Jesus.' },
  { cat: 'nt', level: 2, q: 'In the Beatitudes, who “shall inherit the earth”?', answer: 'The meek', wrong: ['The pure in heart', 'The peacemakers', 'The merciful'], ref: 'Matthew 5:5', fact: 'The pure in heart see God; the peacemakers are called children of God.' },
  { cat: 'nt', level: 2, q: 'How many of the ten healed lepers came back to thank Jesus?', answer: 'One', wrong: ['None', 'Five', 'All ten'], ref: 'Luke 17:15–17', fact: 'The one who returned was a Samaritan.' },
  { cat: 'nt', level: 2, q: 'Which prisoner did the crowd ask Pilate to release instead of Jesus?', answer: 'Barabbas', wrong: ['Malchus', 'Bartimaeus', 'Onesimus'], ref: 'Matthew 27:21', fact: 'A guilty man went free while the innocent one died. That is grace.' },
  { cat: 'nt', level: 2, q: 'Who was made to carry Jesus’ cross?', answer: 'Simon of Cyrene', wrong: ['Simon Peter', 'Joseph of Arimathea', 'John'], ref: 'Mark 15:21', fact: 'Simon was coming in from the country when the soldiers stopped him.' },
  { cat: 'nt', level: 2, q: 'Who was the first person to see Jesus after he rose?', answer: 'Mary Magdalene', wrong: ['Peter', 'John', 'Mary, mother of Jesus'], ref: 'Mark 16:9', fact: 'She thought he was the gardener until he said her name.' },
  { cat: 'nt', level: 2, q: 'How did Jesus leave the earth after forty days?', answer: 'He was taken up and a cloud hid him', wrong: ['In a chariot of fire', 'He walked into the sea', 'He went into a cave'], ref: 'Acts 1:9', fact: 'Angels said he will come back in the same way.' },
  { cat: 'nt', level: 2, q: 'What did John the Baptist eat in the wilderness?', answer: 'Locusts and wild honey', wrong: ['Manna and quail', 'Figs and dates', 'Bread and fish'], ref: 'Matthew 3:4', fact: 'He wore clothes of camel’s hair.' },
  { cat: 'nt', level: 2, q: 'What did the crowds wave when Jesus entered Jerusalem?', answer: 'Palm branches', wrong: ['Olive branches', 'Flags', 'Red cloths'], ref: 'John 12:13', fact: 'They shouted, “Hosanna: Blessed is the King of Israel.”' },
  { cat: 'nt', level: 2, q: 'In Jesus’ story, what job did the lost son end up doing?', answer: 'Feeding pigs', wrong: ['Herding goats', 'Selling fish', 'Carrying water'], ref: 'Luke 15:15', fact: 'He was so hungry he wanted to eat the pigs’ food.' },
  { cat: 'nt', level: 2, q: 'What was the name of the blind beggar healed near Jericho?', answer: 'Bartimaeus', wrong: ['Zacchaeus', 'Lazarus', 'Malchus'], ref: 'Mark 10:46', fact: 'He kept shouting, “Jesus, thou Son of David, have mercy on me.”' },
  { cat: 'nt', level: 2, q: 'Which sister was busy serving while Mary sat listening to Jesus?', answer: 'Martha', wrong: ['Salome', 'Joanna', 'Susanna'], ref: 'Luke 10:40–42', fact: 'Jesus said Mary had chosen the good part.' },
  { cat: 'nt', level: 2, q: 'Which relative of Mary was the mother of John the Baptist?', answer: 'Elizabeth', wrong: ['Anna', 'Salome', 'Joanna'], ref: 'Luke 1:36, 57', fact: 'Her baby leaped inside her when Mary greeted her.' },
  { cat: 'nt', level: 2, q: 'Where did Joseph take Mary and Jesus to escape King Herod?', answer: 'Egypt', wrong: ['Babylon', 'Rome', 'Galilee'], ref: 'Matthew 2:14', fact: 'They stayed there until Herod died.' },
  { cat: 'nt', level: 2, q: 'Jesus said faith as small as what kind of seed could move mountains?', answer: 'A mustard seed', wrong: ['A sesame seed', 'A grain of wheat', 'A fig seed'], ref: 'Matthew 17:20', fact: 'Small faith in a great God goes a long way.' },
  { cat: 'nt', level: 2, q: 'What happened when Paul and Silas sang praises in prison at midnight?', answer: 'An earthquake opened the doors', wrong: ['The guards fell asleep', 'A fire broke out', 'The king set them free'], ref: 'Acts 16:25–26', fact: 'The jailer and his whole family came to believe.' },
  { cat: 'nt', level: 2, q: 'What did Paul and Silas tell the jailer to do to be saved?', answer: 'Believe on the Lord Jesus Christ', wrong: ['Offer a sacrifice at the temple', 'Keep the whole law', 'Give away all he owned'], ref: 'Acts 16:31', fact: 'Salvation is a gift received by faith.' },
  { cat: 'nt', level: 2, q: 'Who went with Paul on his first missionary journey?', answer: 'Barnabas', wrong: ['Silas', 'Luke', 'Timothy'], ref: 'Acts 13:2', fact: 'The Holy Spirit said, “Separate me Barnabas and Saul.”' },
  { cat: 'nt', level: 2, q: 'In the armour of God, what is “the sword of the Spirit”?', answer: 'The word of God', wrong: ['Faith', 'Salvation', 'Truth'], ref: 'Ephesians 6:17', fact: 'Faith is the shield, salvation the helmet and truth the belt.' },
  { cat: 'nt', level: 2, q: 'Which of these is part of the fruit of the Spirit?', answer: 'Gentleness', wrong: ['Wealth', 'Strength', 'Fame'], ref: 'Galatians 5:22–23', fact: 'The list begins with love, joy and peace.' },
  { cat: 'nt', level: 2, q: 'According to Romans 6:23, what is the gift of God?', answer: 'Eternal life through Jesus Christ our Lord', wrong: ['Riches and honour', 'A long life on earth', 'The law of Moses'], ref: 'Romans 6:23', fact: 'The wages of sin is death, but the gift is life.' },
  { cat: 'nt', level: 2, q: 'Romans 3:23 says how many “have sinned, and come short of the glory of God”?', answer: 'All', wrong: ['Most', 'Only the Gentiles', 'Only the wicked'], ref: 'Romans 3:23', fact: 'That is why everyone needs Jesus.' },
  { cat: 'nt', level: 2, q: 'In Revelation, Jesus calls himself Alpha and Omega. What does that mean?', answer: 'The beginning and the end', wrong: ['The king and the priest', 'The lamb and the lion', 'The light and the life'], ref: 'Revelation 22:13', fact: 'Alpha and omega are the first and last letters of the Greek alphabet.' },
  { cat: 'nt', level: 2, q: 'Who rolled back the stone from Jesus’ tomb?', answer: 'An angel of the Lord', wrong: ['Peter and John', 'The Roman guards', 'Joseph of Arimathea'], ref: 'Matthew 28:2', fact: 'Then the angel sat on it!' },
  { cat: 'nt', level: 2, q: 'What sign did the angel give the shepherds to find the baby?', answer: 'Wrapped in swaddling clothes, lying in a manger', wrong: ['A star over the house', 'A dove resting on him', 'A rainbow in the sky'], ref: 'Luke 2:12', fact: 'The shepherds hurried and found him just as they were told.' },
  { cat: 'nt', level: 2, q: 'Who was the old man in the temple promised he would see the Christ before he died?', answer: 'Simeon', wrong: ['Zacharias', 'Eli', 'Nicodemus'], ref: 'Luke 2:25–30', fact: 'He held baby Jesus and said, “Mine eyes have seen thy salvation.”' },
  { cat: 'nt', level: 2, q: 'In the parable of the sower, which seed produced a harvest?', answer: 'Seed on good ground', wrong: ['Seed by the wayside', 'Seed on stony ground', 'Seed among thorns'], ref: 'Matthew 13:8, 23', fact: 'Good ground is a heart that hears the word and understands it.' },
  { cat: 'nt', level: 2, q: 'How did four friends get a paralysed man to Jesus through the crowd?', answer: 'They let him down through the roof', wrong: ['They carried him through a window', 'They asked the crowd to leave', 'They waited until night'], ref: 'Mark 2:3–4', fact: 'Jesus saw their faith and forgave the man’s sins, then healed him.' },
  { cat: 'nt', level: 2, q: 'Which ruler of the synagogue begged Jesus to heal his dying daughter?', answer: 'Jairus', wrong: ['Nicodemus', 'Joseph', 'Cornelius'], ref: 'Mark 5:22–23', fact: 'Jesus told him, “Be not afraid, only believe.”' },
  { cat: 'nt', level: 2, q: 'Who came to Jesus at night with questions?', answer: 'Nicodemus', wrong: ['Zacchaeus', 'Judas', 'Lazarus'], ref: 'John 3:1–2', fact: 'Later he helped bury Jesus’ body.' },
  { cat: 'nt', level: 2, q: 'Who said to Jesus, “Lord, remember me when thou comest into thy kingdom”?', answer: 'A thief on a cross', wrong: ['Peter', 'A Roman soldier', 'Pilate’s wife'], ref: 'Luke 23:42–43', fact: 'Jesus promised, “To day shalt thou be with me in paradise.”' },
  { cat: 'nt', level: 2, q: 'Who said “Truly this was the Son of God” after Jesus died?', answer: 'A Roman centurion', wrong: ['Pilate', 'Caiaphas', 'Herod'], ref: 'Matthew 27:54', fact: 'He and those with him saw the earthquake and feared greatly.' },
  { cat: 'nt', level: 2, q: 'On the road to Damascus, what happened to Saul’s eyes?', answer: 'He was blind for three days', wrong: ['He saw angels everywhere', 'Nothing at all', 'He could see in the dark'], ref: 'Acts 9:8–9', fact: 'Something like scales fell from his eyes when Ananias prayed.' },
  { cat: 'nt', level: 2, q: 'Who spoke boldly to the crowd on the day of Pentecost?', answer: 'Peter', wrong: ['Paul', 'Stephen', 'James'], ref: 'Acts 2:14', fact: 'About three thousand people believed that day.' },
  { cat: 'nt', level: 2, q: 'What did the lame man at the temple gate get instead of money?', answer: 'He was healed in Jesus’ name', wrong: ['A new coat', 'A job at the temple', 'A place to live'], ref: 'Acts 3:6–8', fact: 'Peter said, “Silver and gold have I none; but such as I have give I thee.”' },
  { cat: 'nt', level: 2, q: 'Which letter says “Let no man despise thy youth”?', answer: '1 Timothy', wrong: ['Titus', 'Philemon', 'Jude'], ref: '1 Timothy 4:12', fact: 'Paul told young Timothy to be an example in word, love, faith and purity.' },
  { cat: 'nt', level: 2, q: 'Which chapter of the Bible is often called the love chapter?', answer: '1 Corinthians 13', wrong: ['John 3', 'Romans 8', 'Psalm 23'], ref: '1 Corinthians 13:13', fact: 'It ends with faith, hope and charity, “the greatest of these is charity.”' },

  { cat: 'gen', level: 2, q: 'How many books are in the Old Testament?', answer: '39', wrong: ['27', '46', '50'], ref: 'Genesis to Malachi', fact: 'It begins with creation and ends looking ahead to the Messiah.' },
  { cat: 'gen', level: 2, q: 'How many books are in the New Testament?', answer: '27', wrong: ['39', '22', '33'], ref: 'Matthew to Revelation', fact: 'Four Gospels, Acts, twenty-one letters and Revelation.' },
  { cat: 'gen', level: 2, q: 'Which book comes right after the four Gospels?', answer: 'Acts', wrong: ['Romans', 'Hebrews', 'Revelation'], ref: 'Acts 1:1', fact: 'Luke wrote both his Gospel and Acts.' },
  { cat: 'gen', level: 2, q: 'Which book comes just before Revelation?', answer: 'Jude', wrong: ['3 John', 'Hebrews', 'James'], ref: 'Jude 1:24–25', fact: 'Jude ends with a famous blessing of praise to God.' },
  { cat: 'gen', level: 2, q: 'Which two books of the Bible are named after women?', answer: 'Ruth and Esther', wrong: ['Ruth and Naomi', 'Esther and Deborah', 'Mary and Martha'], ref: 'Ruth 1:4; Esther 2:7', fact: 'One was a Moabite widow, the other an orphan who became queen.' },
  { cat: 'gen', level: 2, q: 'Which book comes right after Acts?', answer: 'Romans', wrong: ['Galatians', '1 Corinthians', 'James'], ref: 'Romans 1:16', fact: 'Paul wrote, “I am not ashamed of the gospel of Christ.”' },
  { cat: 'gen', level: 2, q: 'Which of these books is a letter?', answer: 'Galatians', wrong: ['Lamentations', 'Leviticus', 'Acts'], ref: 'Galatians 1:1–2', fact: 'Paul wrote it to the churches of Galatia.' },
  { cat: 'gen', level: 2, q: 'Which of these is NOT split into “1” and “2” books?', answer: 'Judges', wrong: ['Samuel', 'Kings', 'Chronicles'], ref: 'Judges 1:1', fact: 'Judges tells of leaders like Deborah, Gideon and Samson.' },
  { cat: 'gen', level: 2, q: 'In which book is the verse “Trust in the LORD with all thine heart”?', answer: 'Proverbs', wrong: ['Psalms', 'Isaiah', 'Ecclesiastes'], ref: 'Proverbs 3:5', fact: 'It continues, “and lean not unto thine own understanding.”' },
  { cat: 'gen', level: 2, q: 'Which book holds the verse “Thy word is a lamp unto my feet”?', answer: 'Psalms', wrong: ['Proverbs', 'John', 'Deuteronomy'], ref: 'Psalm 119:105', fact: 'God’s word lights the next step on the path.' },
  { cat: 'gen', level: 2, q: 'What is the last book of the Old Testament?', answer: 'Malachi', wrong: ['Zechariah', 'Nehemiah', 'Daniel'], ref: 'Malachi 4:5', fact: 'Malachi promised that Elijah would come first. Jesus said John the Baptist fulfilled it.' },
  { cat: 'gen', level: 2, q: 'The titles “Messiah” and “Christ” both mean what?', answer: 'Anointed One', wrong: ['Holy Teacher', 'Son of David', 'King of Peace'], ref: 'John 1:41', fact: 'Andrew told Peter, “We have found the Messias.”' },
  { cat: 'gen', level: 2, q: 'What does “Rabbi” mean in the Gospels?', answer: 'Master or teacher', wrong: ['Priest', 'Prophet', 'Friend'], ref: 'John 1:38', fact: 'Two disciples called Jesus Rabbi on the first day they followed him.' },
  { cat: 'gen', level: 2, q: 'Paul wrote two letters to which young helper?', answer: 'Timothy', wrong: ['Titus', 'Mark', 'Silas'], ref: '1 Timothy 1:2', fact: 'Paul called him “my own son in the faith”.' },
  { cat: 'gen', level: 2, q: 'Which Gospel was written by a fisherman Jesus loved?', answer: 'John', wrong: ['Mark', 'Luke', 'Matthew'], ref: 'John 21:20, 24', fact: 'John calls himself “the disciple whom Jesus loved”.' },
  { cat: 'gen', level: 2, q: 'Which Gospel tells about the shepherds visiting baby Jesus?', answer: 'Luke', wrong: ['Matthew', 'Mark', 'John'], ref: 'Luke 2:8–16', fact: 'Matthew tells about the wise men instead.' },

  // ---------- More level 3: hard ----------
  { cat: 'ot', level: 3, q: 'Where did Jonah try to sail to when he ran from God?', answer: 'Tarshish', wrong: ['Nineveh', 'Joppa', 'Tyre'], ref: 'Jonah 1:3', fact: 'He found the ship at Joppa, heading the opposite way from Nineveh.' },
  { cat: 'ot', level: 3, q: 'Who told the sun to stand still during a battle?', answer: 'Joshua', wrong: ['Gideon', 'Elijah', 'Moses'], ref: 'Joshua 10:12–13', fact: 'The sun stood still until Israel had won the day.' },
  { cat: 'ot', level: 3, q: 'What were the names of Noah’s three sons?', answer: 'Shem, Ham and Japheth', wrong: ['Cain, Abel and Seth', 'Reuben, Simeon and Levi', 'Enoch, Irad and Lamech'], ref: 'Genesis 6:10', fact: 'All the nations of the earth came from these three.' },
  { cat: 'ot', level: 3, q: 'Which Egyptian maid of Sarah became the mother of Ishmael?', answer: 'Hagar', wrong: ['Zilpah', 'Bilhah', 'Keturah'], ref: 'Genesis 16:15', fact: 'Hagar called God “Thou God seest me.”' },
  { cat: 'ot', level: 3, q: 'Who was Rebekah’s brother, later Jacob’s tricky father-in-law?', answer: 'Laban', wrong: ['Bethuel', 'Nahor', 'Lot'], ref: 'Genesis 29:16, 25', fact: 'Laban swapped Leah for Rachel on Jacob’s wedding night.' },
  { cat: 'ot', level: 3, q: 'How many years did Jacob first agree to work for Rachel?', answer: 'Seven', wrong: ['Three', 'Twelve', 'Twenty'], ref: 'Genesis 29:18–20', fact: 'He ended up working seven more.' },
  { cat: 'ot', level: 3, q: 'What were the names of Joseph’s two sons born in Egypt?', answer: 'Manasseh and Ephraim', wrong: ['Perez and Zerah', 'Gershom and Eliezer', 'Mahlon and Chilion'], ref: 'Genesis 41:51–52', fact: 'Both sons became tribes of Israel.' },
  { cat: 'ot', level: 3, q: 'Who was the Egyptian officer who bought Joseph as a slave?', answer: 'Potiphar', wrong: ['Pharaoh', 'Shishak', 'Poti-pherah'], ref: 'Genesis 39:1', fact: 'The Lord was with Joseph, and he prospered even as a slave.' },
  { cat: 'ot', level: 3, q: 'Where was Joseph’s silver cup hidden to test his brothers?', answer: 'In Benjamin’s sack', wrong: ['In Judah’s sack', 'In Reuben’s tent', 'Under Simeon’s cloak'], ref: 'Genesis 44:12', fact: 'Judah offered to stay as a slave in Benjamin’s place.' },
  { cat: 'ot', level: 3, q: 'In which part of Egypt did Jacob’s family settle?', answer: 'Goshen', wrong: ['Zoan', 'Memphis', 'Sinai'], ref: 'Genesis 47:27', fact: 'There they grew and multiplied greatly.' },
  { cat: 'ot', level: 3, q: 'Who was Moses’ wife?', answer: 'Zipporah', wrong: ['Miriam', 'Jochebed', 'Keturah'], ref: 'Exodus 2:21', fact: 'She was one of the seven daughters of the priest of Midian.' },
  { cat: 'ot', level: 3, q: 'What did Moses lift up on a pole so bitten people could look and live?', answer: 'A serpent of brass', wrong: ['A golden calf', 'The ark of the covenant', 'A silver trumpet'], ref: 'Numbers 21:9', fact: 'Jesus said he too must be lifted up, so that believers have eternal life (John 3:14–15).' },
  { cat: 'ot', level: 3, q: 'What did Rahab tie in her window so her family would be spared?', answer: 'A scarlet cord', wrong: ['A white cloth', 'A palm branch', 'A lamp'], ref: 'Joshua 2:18, 21', fact: 'Her whole family was saved when Jericho fell.' },
  { cat: 'ot', level: 3, q: 'Which woman killed the enemy general Sisera with a tent peg?', answer: 'Jael', wrong: ['Deborah', 'Delilah', 'Abigail'], ref: 'Judges 4:21', fact: 'Deborah had said a woman would win the honour of that victory.' },
  { cat: 'ot', level: 3, q: 'What did Samson use to defeat a thousand Philistines?', answer: 'The jawbone of a donkey', wrong: ['A wooden club', 'A sling and stones', 'The gates of Gaza'], ref: 'Judges 15:15', fact: 'Samson carried off the gates of Gaza on another day.' },
  { cat: 'ot', level: 3, q: 'From which people did Ruth come?', answer: 'Moab', wrong: ['Edom', 'Egypt', 'Philistia'], ref: 'Ruth 1:4', fact: 'God welcomed an outsider into the family line of Jesus.' },
  { cat: 'ot', level: 3, q: 'Which daughter of King Saul married David?', answer: 'Michal', wrong: ['Merab', 'Abigail', 'Tamar'], ref: '1 Samuel 18:27', fact: 'Michal later helped David escape through a window.' },
  { cat: 'ot', level: 3, q: 'Whose wise wife stopped David from taking revenge on her foolish husband Nabal?', answer: 'Abigail', wrong: ['Bathsheba', 'Michal', 'Ahinoam'], ref: '1 Samuel 25:3, 32–33', fact: 'David thanked God for sending her.' },
  { cat: 'ot', level: 3, q: 'Which lame son of Jonathan did David invite to eat at his table?', answer: 'Mephibosheth', wrong: ['Ish-bosheth', 'Ziba', 'Amasa'], ref: '2 Samuel 9:6–7', fact: 'David showed him kindness for Jonathan’s sake: a picture of grace.' },
  { cat: 'ot', level: 3, q: 'How was Absalom caught as he fled in battle?', answer: 'His head got stuck in an oak tree', wrong: ['His horse threw him into a river', 'He fell into a pit', 'He was trapped in a cave'], ref: '2 Samuel 18:9', fact: 'His mule kept going and left him hanging.' },
  { cat: 'ot', level: 3, q: 'Who was the Hittite soldier, husband of Bathsheba?', answer: 'Uriah', wrong: ['Joab', 'Ahithophel', 'Benaiah'], ref: '2 Samuel 11:3', fact: 'David had Uriah put in the hottest part of the battle.' },
  { cat: 'ot', level: 3, q: 'Who was the commander of David’s army?', answer: 'Joab', wrong: ['Abner', 'Uriah', 'Amasa'], ref: '2 Samuel 8:16', fact: 'Joab was the son of David’s sister Zeruiah.' },
  { cat: 'ot', level: 3, q: 'Whose harsh answer made the ten northern tribes break away from Judah?', answer: 'Rehoboam', wrong: ['Jeroboam', 'Solomon', 'Asa'], ref: '1 Kings 12:13–16', fact: 'He ignored the old men’s advice and listened to his young friends.' },
  { cat: 'ot', level: 3, q: 'Whose vineyard did King Ahab and Jezebel take?', answer: 'Naboth', wrong: ['Nabal', 'Obadiah', 'Micaiah'], ref: '1 Kings 21:1, 15–16', fact: 'Elijah came to Ahab with God’s judgment for it.' },
  { cat: 'ot', level: 3, q: 'For which widow did God make the flour and oil last during a famine?', answer: 'The widow of Zarephath', wrong: ['The widow of Nain', 'Naomi', 'The widow of Shunem'], ref: '1 Kings 17:9, 16', fact: 'She fed Elijah first, and the jar never ran out.' },
  { cat: 'ot', level: 3, q: 'How did God speak to Elijah on Mount Horeb?', answer: 'In a still small voice', wrong: ['In a great wind', 'In an earthquake', 'In a fire'], ref: '1 Kings 19:11–12', fact: 'God was not in the wind, earthquake or fire.' },
  { cat: 'ot', level: 3, q: 'What did Elisha ask Elijah for before Elijah was taken up?', answer: 'A double portion of his spirit', wrong: ['His chariot', 'A long life', 'Great riches'], ref: '2 Kings 2:9', fact: 'Elisha went on to do many miracles.' },
  { cat: 'ot', level: 3, q: 'Whose son did Elisha raise to life in the town of Shunem?', answer: 'The Shunammite woman’s', wrong: ['The widow of Zarephath’s', 'Naaman’s', 'Jairus’s'], ref: '2 Kings 4:32–35', fact: 'She had made a little room for Elisha on her roof.' },
  { cat: 'ot', level: 3, q: 'Why did a seraph touch Isaiah’s lips with a live coal?', answer: 'To take away his sin', wrong: ['To give him visions', 'To punish him for doubting', 'To make his voice louder'], ref: 'Isaiah 6:6–7', fact: 'Then Isaiah was ready to say, “Here am I; send me.”' },
  { cat: 'ot', level: 3, q: 'Which prophet was let down into a muddy dungeon with ropes?', answer: 'Jeremiah', wrong: ['Isaiah', 'Amos', 'Micah'], ref: 'Jeremiah 38:6', fact: 'He sank into the mire, but God sent someone to pull him out.' },
  { cat: 'ot', level: 3, q: 'What did Daniel and his friends eat instead of the king’s food?', answer: 'Pulse and water', wrong: ['Bread and wine', 'Fish and honey', 'Nothing at all'], ref: 'Daniel 1:12–15', fact: 'After ten days they looked healthier than the others.' },
  { cat: 'ot', level: 3, q: 'Which king lived like an animal, eating grass, until he honoured God?', answer: 'Nebuchadnezzar', wrong: ['Belshazzar', 'Darius', 'Ahab'], ref: 'Daniel 4:33–34', fact: 'When his mind came back, he praised the King of heaven.' },
  { cat: 'ot', level: 3, q: 'What was Nehemiah’s job in the Persian king’s palace?', answer: 'Cupbearer', wrong: ['Chief baker', 'Royal scribe', 'Captain of the guard'], ref: 'Nehemiah 1:11', fact: 'The king noticed Nehemiah’s sad face and let him go to rebuild Jerusalem.' },
  { cat: 'ot', level: 3, q: 'Which scribe read the Law aloud to the people from a wooden platform?', answer: 'Ezra', wrong: ['Baruch', 'Shaphan', 'Nehemiah'], ref: 'Nehemiah 8:4–5', fact: 'The people stood up as soon as he opened the book.' },
  { cat: 'ot', level: 3, q: 'What did God make grow to shade Jonah outside Nineveh?', answer: 'A gourd plant', wrong: ['A fig tree', 'A palm tree', 'A cedar'], ref: 'Jonah 4:6', fact: 'God used it to teach Jonah about his mercy for the city.' },
  { cat: 'ot', level: 3, q: 'Which prophet foretold that the ruler of Israel would come from Bethlehem?', answer: 'Micah', wrong: ['Malachi', 'Hosea', 'Joel'], ref: 'Micah 5:2', fact: 'The chief priests quoted it when the wise men asked where Christ would be born.' },
  { cat: 'ot', level: 3, q: 'Which prophet wrote, “with his stripes we are healed”?', answer: 'Isaiah', wrong: ['Jeremiah', 'Ezekiel', 'Zechariah'], ref: 'Isaiah 53:5', fact: 'Peter applied these words to Jesus on the cross (1 Peter 2:24).' },
  { cat: 'ot', level: 3, q: 'How old was Moses when he died?', answer: '120', wrong: ['80', '100', '175'], ref: 'Deuteronomy 34:7', fact: 'His eye was not dim, nor his strength gone.' },
  { cat: 'ot', level: 3, q: 'Why was Moses not allowed to enter the Promised Land?', answer: 'He struck the rock instead of speaking to it', wrong: ['He made the golden calf', 'He killed an Egyptian', 'He refused to cross the Jordan'], ref: 'Numbers 20:8–12', fact: 'God still let him see the land from a mountaintop.' },
  { cat: 'ot', level: 3, q: 'Whose rod budded, blossomed and grew almonds overnight?', answer: 'Aaron’s', wrong: ['Moses’', 'Korah’s', 'Joshua’s'], ref: 'Numbers 17:8', fact: 'It showed God had chosen Aaron’s family as priests.' },
  { cat: 'ot', level: 3, q: 'What did the spies carry back on a pole from the valley of Eshcol?', answer: 'A huge cluster of grapes', wrong: ['A giant’s sword', 'A basket of figs only', 'A golden idol'], ref: 'Numbers 13:23', fact: 'The land really did flow with milk and honey.' },
  { cat: 'ot', level: 3, q: 'To which land was Abraham told to take Isaac to offer him?', answer: 'In the land of Moriah', wrong: ['Mount Sinai', 'Mount Carmel', 'Mount Nebo'], ref: 'Genesis 22:2', fact: 'Solomon later built the temple on Mount Moriah (2 Chronicles 3:1).' },
  { cat: 'ot', level: 3, q: 'What name did Abraham give the place where God provided the ram?', answer: 'Jehovah-jireh', wrong: ['Jehovah-nissi', 'Bethel', 'Ebenezer'], ref: 'Genesis 22:14', fact: 'It means “the LORD will provide”.' },
  { cat: 'ot', level: 3, q: 'From which city did Abram’s family first set out?', answer: 'Ur of the Chaldees', wrong: ['Nineveh', 'Damascus', 'Sodom'], ref: 'Genesis 11:31', fact: 'They stopped at Haran before Abram went on to Canaan.' },
  { cat: 'ot', level: 3, q: 'In whose field did Ruth glean barley?', answer: 'Boaz’s', wrong: ['Elimelech’s', 'Obed’s', 'Jesse’s'], ref: 'Ruth 2:3', fact: 'Boaz told his workers to leave extra grain for her on purpose.' },
  { cat: 'ot', level: 3, q: 'Which judge made a foolish vow before fighting the Ammonites?', answer: 'Jephthah', wrong: ['Gideon', 'Ehud', 'Samson'], ref: 'Judges 11:30–31', fact: 'His story warns us to think before we promise.' },
  { cat: 'ot', level: 3, q: 'Whose sons Hophni and Phinehas were wicked priests?', answer: 'Eli’s', wrong: ['Samuel’s', 'Aaron’s', 'Zadok’s'], ref: '1 Samuel 2:12, 34', fact: 'Young Samuel grew up serving the Lord in Eli’s house.' },

  { cat: 'nt', level: 3, q: 'Whose request led to John the Baptist being beheaded?', answer: 'Herodias, through her daughter', wrong: ['Pilate’s wife', 'Caiaphas', 'Herod’s soldiers'], ref: 'Mark 6:24–27', fact: 'John had told Herod it was not lawful to have his brother’s wife.' },
  { cat: 'nt', level: 3, q: 'Where did Jesus tell the blind man to wash after putting clay on his eyes?', answer: 'The pool of Siloam', wrong: ['The pool of Bethesda', 'The Jordan River', 'Jacob’s well'], ref: 'John 9:7', fact: 'He said, “One thing I know, that, whereas I was blind, now I see.”' },
  { cat: 'nt', level: 3, q: 'How long had the woman who touched Jesus’ garment been ill?', answer: 'Twelve years', wrong: ['Three years', 'Eighteen years', 'Thirty-eight years'], ref: 'Mark 5:25–29', fact: 'Jesus told her, “Daughter, thy faith hath made thee whole.”' },
  { cat: 'nt', level: 3, q: 'What name did the demons in the man of the Gadarenes give?', answer: 'Legion', wrong: ['Beelzebub', 'Abaddon', 'Mammon'], ref: 'Mark 5:9', fact: 'Afterwards the man sat clothed and in his right mind.' },
  { cat: 'nt', level: 3, q: 'How many baskets of leftovers were gathered after the five thousand were fed?', answer: 'Twelve', wrong: ['Seven', 'Five', 'Two'], ref: 'John 6:13', fact: 'Nothing was wasted.' },
  { cat: 'nt', level: 3, q: 'In the parable of the talents, how many talents did the first servant receive?', answer: 'Five', wrong: ['Ten', 'Two', 'One'], ref: 'Matthew 25:15', fact: 'He traded with them and made five more.' },
  { cat: 'nt', level: 3, q: 'In the parable of the ten virgins, how many were wise?', answer: 'Five', wrong: ['Three', 'Seven', 'One'], ref: 'Matthew 25:2', fact: 'The wise took oil for their lamps and were ready.' },
  { cat: 'nt', level: 3, q: 'What did the merchant sell everything to buy in Jesus’ parable?', answer: 'One pearl of great price', wrong: ['A field of gold', 'A herd of camels', 'A royal robe'], ref: 'Matthew 13:45–46', fact: 'The kingdom of heaven is worth more than everything else.' },
  { cat: 'nt', level: 3, q: 'In Jesus’ parable, how many silver coins did the woman have before losing one?', answer: 'Ten', wrong: ['Five', 'Seven', 'Thirty'], ref: 'Luke 15:8', fact: 'She swept the whole house until she found it.' },
  { cat: 'nt', level: 3, q: 'In the temple parable, who went home right with God?', answer: 'The tax collector who prayed for mercy', wrong: ['The Pharisee who fasted twice a week', 'Both of them', 'Neither of them'], ref: 'Luke 18:13–14', fact: 'He prayed, “God be merciful to me a sinner.”' },
  { cat: 'nt', level: 3, q: 'What does “Golgotha” mean?', answer: 'The place of a skull', wrong: ['The hill of olives', 'The garden of tombs', 'The house of mercy'], ref: 'Mark 15:22', fact: 'It was outside the city, where Jesus was crucified.' },
  { cat: 'nt', level: 3, q: 'Which rich man from Arimathea buried Jesus in his own new tomb?', answer: 'Joseph', wrong: ['Nicodemus', 'Lazarus', 'Simon'], ref: 'Matthew 27:57–60', fact: 'He was a disciple of Jesus who asked Pilate for the body.' },
  { cat: 'nt', level: 3, q: 'To which village were two disciples walking when the risen Jesus joined them?', answer: 'Emmaus', wrong: ['Bethany', 'Cana', 'Nain'], ref: 'Luke 24:13–15', fact: 'They recognised him when he broke bread.' },
  { cat: 'nt', level: 3, q: 'For how many days did the risen Jesus appear to his followers before going up?', answer: 'Forty', wrong: ['Three', 'Seven', 'Fifty'], ref: 'Acts 1:3', fact: 'He spoke to them about the kingdom of God.' },
  { cat: 'nt', level: 3, q: 'About how many people believed and were baptized on the day of Pentecost?', answer: 'Three thousand', wrong: ['Five hundred', 'Five thousand', 'Twelve thousand'], ref: 'Acts 2:41', fact: 'They kept meeting for teaching, fellowship, breaking bread and prayer.' },
  { cat: 'nt', level: 3, q: 'At which temple gate did Peter heal a man lame from birth?', answer: 'The gate called Beautiful', wrong: ['The Sheep Gate', 'The Fish Gate', 'The Water Gate'], ref: 'Acts 3:2', fact: 'The man went walking, leaping and praising God.' },
  { cat: 'nt', level: 3, q: 'Which couple lied about the money from selling their land?', answer: 'Ananias and Sapphira', wrong: ['Aquila and Priscilla', 'Zacharias and Elizabeth', 'Andronicus and Junia'], ref: 'Acts 5:1–2', fact: 'Peter said they had lied not to men but to God.' },
  { cat: 'nt', level: 3, q: 'What was the Ethiopian official reading when Philip met him?', answer: 'The prophet Isaiah', wrong: ['The Psalms', 'The book of Moses', 'A letter from Paul'], ref: 'Acts 8:28–35', fact: 'Philip began at that very scripture and preached Jesus to him.' },
  { cat: 'nt', level: 3, q: 'Which disciple in Damascus was sent to lay hands on blinded Saul?', answer: 'Ananias', wrong: ['Barnabas', 'Silas', 'Philip'], ref: 'Acts 9:10–17', fact: 'He was afraid, but he obeyed and called Saul “Brother”.' },
  { cat: 'nt', level: 3, q: 'How did Saul escape from Damascus when his enemies watched the gates?', answer: 'He was let down the wall in a basket', wrong: ['He hid in a cart of hay', 'He sailed away at night', 'He dressed as a soldier'], ref: 'Acts 9:24–25', fact: 'His fellow believers helped him escape at night.' },
  { cat: 'nt', level: 3, q: 'Which kind woman in Joppa did Peter raise from the dead?', answer: 'Tabitha (Dorcas)', wrong: ['Lydia', 'Priscilla', 'Rhoda'], ref: 'Acts 9:36–40', fact: 'She was known for making coats and clothes for widows.' },
  { cat: 'nt', level: 3, q: 'Which Roman centurion was among the first Gentiles to receive the Holy Spirit?', answer: 'Cornelius', wrong: ['Julius', 'Claudius Lysias', 'Felix'], ref: 'Acts 10:1, 44–45', fact: 'Peter learned that God shows no partiality.' },
  { cat: 'nt', level: 3, q: 'What did Peter see let down from heaven in his rooftop vision?', answer: 'A sheet full of all kinds of animals', wrong: ['A ladder of angels', 'A golden scroll', 'A chariot of fire'], ref: 'Acts 10:11–12', fact: 'God said, “What God hath cleansed, that call not thou common.”' },
  { cat: 'nt', level: 3, q: 'Which seller of purple cloth opened her heart to Paul’s message at Philippi?', answer: 'Lydia', wrong: ['Priscilla', 'Phoebe', 'Damaris'], ref: 'Acts 16:14', fact: 'She opened her home to Paul and his friends.' },
  { cat: 'nt', level: 3, q: 'In Athens, Paul spoke about an altar dedicated to whom?', answer: 'The unknown god', wrong: ['Zeus', 'Caesar', 'The goddess Diana'], ref: 'Acts 17:23', fact: 'Paul told them about the God who made the world and raised Jesus.' },
  { cat: 'nt', level: 3, q: 'When on trial, to whom did Paul appeal as a Roman citizen?', answer: 'Caesar', wrong: ['The high priest', 'King Agrippa', 'The Sanhedrin'], ref: 'Acts 25:11', fact: 'That is how Paul ended up preaching in Rome.' },
  { cat: 'nt', level: 3, q: 'Which of the seven churches in Revelation was “lukewarm”?', answer: 'Laodicea', wrong: ['Smyrna', 'Philadelphia', 'Sardis'], ref: 'Revelation 3:15–16', fact: 'Jesus still knocks at the door and invites them in.' },
  { cat: 'nt', level: 3, q: 'What were each of the twelve gates of the New Jerusalem made of?', answer: 'A single pearl', wrong: ['Pure gold', 'Jasper', 'Cedar wood'], ref: 'Revelation 21:21', fact: 'The street of the city was pure gold, like clear glass.' },
  { cat: 'nt', level: 3, q: 'Which disciple did Jesus first call “Cephas”?', answer: 'Simon Peter', wrong: ['Andrew', 'Nathanael', 'James'], ref: 'John 1:42', fact: 'Cephas means “a stone”.' },
  { cat: 'nt', level: 3, q: 'Which disciple, brought by Philip, asked “Can there any good thing come out of Nazareth?”', answer: 'Nathanael', wrong: ['Thomas', 'Andrew', 'Judas'], ref: 'John 1:45–46', fact: 'Philip simply said, “Come and see.”' },
  { cat: 'nt', level: 3, q: 'In the parable of the talents, which servant hid his money in the ground?', answer: 'The one given one talent', wrong: ['The one given five talents', 'The one given two talents', 'The master’s steward'], ref: 'Matthew 25:18, 25', fact: 'He said he was afraid; the others were faithful with what they had.' },
  { cat: 'nt', level: 3, q: 'Which Pharisee came with Joseph of Arimathea, bringing myrrh and aloes for Jesus’ burial?', answer: 'Nicodemus', wrong: ['Gamaliel', 'Simon', 'Jairus'], ref: 'John 19:39', fact: 'He brought about a hundred pound weight of spices.' },
  { cat: 'nt', level: 3, q: 'Which husband-and-wife tentmakers explained the way of God more fully to Apollos?', answer: 'Aquila and Priscilla', wrong: ['Ananias and Sapphira', 'Philemon and Apphia', 'Andronicus and Junia'], ref: 'Acts 18:26', fact: 'They took him aside kindly instead of shaming him.' },
  { cat: 'nt', level: 3, q: 'Which young man fell from a third-floor window while Paul preached late into the night?', answer: 'Eutychus', wrong: ['Trophimus', 'Tychicus', 'Timothy'], ref: 'Acts 20:9–12', fact: 'Paul went down, embraced him, and the young man was brought back alive.' },
  { cat: 'nt', level: 3, q: 'What did the Pharisees try to trap Jesus with when they asked about a coin?', answer: 'Whether to pay tribute to Caesar', wrong: ['Whether to give to the temple', 'Whether to lend money', 'Whether to keep the Sabbath'], ref: 'Matthew 22:17–21', fact: 'Jesus said, “Render therefore unto Caesar the things which are Caesar’s; and unto God the things that are God’s.”' },

  { cat: 'gen', level: 3, q: 'Which of these books has only one chapter?', answer: 'Jude', wrong: ['Titus', 'James', 'Ruth'], ref: 'Jude', fact: 'Obadiah, Philemon, 2 John and 3 John also have one chapter.' },
  { cat: 'gen', level: 3, q: 'How many books are known as the Minor Prophets?', answer: 'Twelve', wrong: ['Four', 'Seven', 'Seventeen'], ref: 'Hosea to Malachi', fact: '“Minor” means shorter, not less important.' },
  { cat: 'gen', level: 3, q: 'Which Gospel contains the Sermon on the Mount?', answer: 'Matthew', wrong: ['Mark', 'John', 'Acts'], ref: 'Matthew 5–7', fact: 'It includes the Beatitudes and the Lord’s Prayer.' },
  { cat: 'gen', level: 3, q: 'Which Gospel tells the parable of the prodigal son?', answer: 'Luke', wrong: ['Matthew', 'Mark', 'John'], ref: 'Luke 15:11–32', fact: 'Luke 15 has three “lost” stories: a sheep, a coin and a son.' },
  { cat: 'gen', level: 3, q: 'Which book comes right after Isaiah?', answer: 'Jeremiah', wrong: ['Ezekiel', 'Lamentations', 'Daniel'], ref: 'Jeremiah 1:1', fact: 'Lamentations follows Jeremiah.' },
  { cat: 'gen', level: 3, q: 'Which book comes between Joshua and Ruth?', answer: 'Judges', wrong: ['1 Samuel', 'Numbers', 'Deuteronomy'], ref: 'Judges 21:25', fact: 'Judges ends, “every man did that which was right in his own eyes.”' },
  { cat: 'gen', level: 3, q: 'Which book comes right after Nehemiah?', answer: 'Esther', wrong: ['Ezra', 'Job', 'Ruth'], ref: 'Esther 1:1', fact: 'Ezra, Nehemiah and Esther all come from the time after the exile.' },
  { cat: 'gen', level: 3, q: 'Which book comes right after Ruth?', answer: '1 Samuel', wrong: ['Judges', '1 Kings', '1 Chronicles'], ref: '1 Samuel 1:1', fact: 'Ruth ends with David’s family line, and 1 Samuel leads up to David.' },
  { cat: 'gen', level: 3, q: 'Which New Testament chapter lists heroes of faith like Abel, Noah and Abraham?', answer: 'Hebrews 11', wrong: ['Romans 8', 'James 2', 'Revelation 7'], ref: 'Hebrews 11:1', fact: 'Hebrews 12 then says to look to Jesus, the author and finisher of our faith.' },
  { cat: 'gen', level: 3, q: 'What does “Hallelujah” (Alleluia) mean?', answer: 'Praise the Lord', wrong: ['God is with us', 'So be it', 'Come, Lord'], ref: 'Revelation 19:1', fact: 'Heaven’s crowd shouts it in Revelation 19.' },
  { cat: 'gen', level: 3, q: 'What does “Abba”, used by Jesus in prayer, mean?', answer: 'Father', wrong: ['Lord', 'Teacher', 'Holy One'], ref: 'Mark 14:36', fact: 'Paul says believers can cry “Abba, Father” too (Romans 8:15).' },
  { cat: 'gen', level: 3, q: 'The name Moses is linked to which event in his life?', answer: 'Being drawn out of the water', wrong: ['Seeing the burning bush', 'Crossing the Red Sea', 'Climbing Mount Sinai'], ref: 'Exodus 2:10', fact: 'Pharaoh’s daughter said, “Because I drew him out of the water.”' },
  { cat: 'gen', level: 3, q: 'In “New Testament”, what does the word “testament” mean?', answer: 'Covenant', wrong: ['Story', 'Law', 'History'], ref: 'Luke 22:20', fact: 'Jesus said, “This cup is the new testament in my blood.”' },
  { cat: 'gen', level: 3, q: 'In which book is the verse “Remember now thy Creator in the days of thy youth”?', answer: 'Ecclesiastes', wrong: ['Proverbs', 'Psalms', 'Song of Solomon'], ref: 'Ecclesiastes 12:1', fact: 'It is a great word for young people.' },
  { cat: 'nt', level: 3, q: 'Which three disciples saw Jesus’ Transfiguration?', answer: 'Peter, James and John', wrong: ['Peter, Andrew and Philip', 'James, John and Thomas', 'Matthew, Mark and Luke'], ref: 'Matthew 17:1', fact: 'Jesus took the same three further into Gethsemane.' },

  // ---------- More level 4: expert ----------
  { cat: 'ot', level: 4, q: 'Who was the father of Methuselah?', answer: 'Enoch', wrong: ['Lamech', 'Jared', 'Seth'], ref: 'Genesis 5:21', fact: 'Enoch walked with God, and God took him.' },
  { cat: 'ot', level: 4, q: 'Who was the father of Noah?', answer: 'Lamech', wrong: ['Methuselah', 'Enoch', 'Jared'], ref: 'Genesis 5:28–29', fact: 'Lamech hoped his son would bring comfort from the hard toil of the ground.' },
  { cat: 'ot', level: 4, q: 'Who was Abraham’s father?', answer: 'Terah', wrong: ['Nahor', 'Haran', 'Serug'], ref: 'Genesis 11:26', fact: 'Terah moved the family from Ur toward Canaan.' },
  { cat: 'ot', level: 4, q: 'What Egyptian name was Joseph’s wife called?', answer: 'Asenath', wrong: ['Zipporah', 'Keturah', 'Zilpah'], ref: 'Genesis 41:45', fact: 'She was the daughter of Poti-pherah, priest of On.' },
  { cat: 'ot', level: 4, q: 'What did Moses name his first son, saying “I have been a stranger in a strange land”?', answer: 'Gershom', wrong: ['Eliezer', 'Eleazar', 'Elkanah'], ref: 'Exodus 2:22', fact: 'Moses was living in Midian at the time.' },
  { cat: 'ot', level: 4, q: 'What were the names of the brave Hebrew midwives who would not kill the baby boys?', answer: 'Shiphrah and Puah', wrong: ['Bilhah and Zilpah', 'Mahlah and Noah', 'Adah and Zillah'], ref: 'Exodus 1:15–17', fact: 'They feared God more than Pharaoh, and God blessed them.' },
  { cat: 'ot', level: 4, q: 'Which two sons of Aaron offered “strange fire” before the Lord?', answer: 'Nadab and Abihu', wrong: ['Eleazar and Ithamar', 'Hophni and Phinehas', 'Korah and Dathan'], ref: 'Leviticus 10:1–2', fact: 'Worship is to be offered God’s way, not our own.' },
  { cat: 'ot', level: 4, q: 'Who took forbidden treasure from Jericho and caused Israel’s defeat at Ai?', answer: 'Achan', wrong: ['Achish', 'Abiram', 'Agag'], ref: 'Joshua 7:1, 21', fact: 'He hid a Babylonish garment, silver and gold in his tent.' },
  { cat: 'ot', level: 4, q: 'How old was Caleb when he asked Joshua for his mountain?', answer: '85', wrong: ['40', '70', '120'], ref: 'Joshua 14:10–12', fact: 'He said he was as strong as on the day Moses sent him.' },
  { cat: 'ot', level: 4, q: 'Which judge killed six hundred Philistines with an ox goad?', answer: 'Shamgar', wrong: ['Ehud', 'Tola', 'Ibzan'], ref: 'Judges 3:31', fact: 'His whole story fits in one verse.' },
  { cat: 'ot', level: 4, q: 'Who was the father of King Saul?', answer: 'Kish', wrong: ['Ner', 'Abner', 'Jesse'], ref: '1 Samuel 9:1–2', fact: 'Saul was out searching for his father’s lost donkeys when he met Samuel.' },
  { cat: 'ot', level: 4, q: 'Which Amalekite king did Saul spare against God’s command?', answer: 'Agag', wrong: ['Og', 'Sihon', 'Eglon'], ref: '1 Samuel 15:8–9', fact: 'Samuel said, “To obey is better than sacrifice.”' },
  { cat: 'ot', level: 4, q: 'Who died after touching the ark of God when the oxen stumbled?', answer: 'Uzzah', wrong: ['Ahio', 'Obed-edom', 'Uzziah'], ref: '2 Samuel 6:6–7', fact: 'The ark then stayed three months in the house of Obed-edom, who was blessed.' },
  { cat: 'ot', level: 4, q: 'How many years did Solomon take to build the temple?', answer: 'Seven', wrong: ['Three', 'Twelve', 'Forty'], ref: '1 Kings 6:38', fact: 'He took thirteen years to build his own house (1 Kings 7:1).' },
  { cat: 'ot', level: 4, q: 'Where did Jeroboam set up golden calves for the northern tribes?', answer: 'Bethel and Dan', wrong: ['Samaria and Jezreel', 'Shiloh and Gilgal', 'Hebron and Beersheba'], ref: '1 Kings 12:28–29', fact: 'He did not want the people going to Jerusalem to worship.' },
  { cat: 'ot', level: 4, q: 'Who was Elisha’s servant, struck with Naaman’s leprosy for his greed?', answer: 'Gehazi', wrong: ['Baruch', 'Ziba', 'Obadiah'], ref: '2 Kings 5:20, 27', fact: 'He ran after Naaman to get the gifts Elisha had refused.' },
  { cat: 'ot', level: 4, q: 'What did Elisha make float on the water of the Jordan?', answer: 'A borrowed axe head', wrong: ['A millstone', 'A bronze shield', 'A clay jar of oil'], ref: '2 Kings 6:5–6', fact: 'The man had cried, “Alas, master! for it was borrowed.”' },
  { cat: 'ot', level: 4, q: 'How many years did God add to King Hezekiah’s life?', answer: 'Fifteen', wrong: ['Five', 'Ten', 'Forty'], ref: '2 Kings 20:6', fact: 'As a sign, the shadow on the sundial went back ten degrees.' },
  { cat: 'ot', level: 4, q: 'Which king was known for driving his chariot “furiously”?', answer: 'Jehu', wrong: ['Ahab', 'Jehoram', 'Omri'], ref: '2 Kings 9:20', fact: 'The watchman recognised him by the way he drove.' },
  { cat: 'ot', level: 4, q: 'How old was Jehoash (Joash) when he became king of Judah?', answer: 'Seven', wrong: ['Eight', 'Twelve', 'Sixteen'], ref: '2 Kings 11:21', fact: 'He had been hidden in the temple for six years from wicked Athaliah.' },
  { cat: 'ot', level: 4, q: 'Which king of Judah was struck with leprosy for burning incense in the temple?', answer: 'Uzziah', wrong: ['Hezekiah', 'Jotham', 'Ahaz'], ref: '2 Chronicles 26:19–21', fact: 'Isaiah’s vision of the Lord came in the year Uzziah died.' },
  { cat: 'ot', level: 4, q: 'Which Ethiopian palace official rescued Jeremiah from the dungeon?', answer: 'Ebed-melech', wrong: ['Baruch', 'Gedaliah', 'Pashur'], ref: 'Jeremiah 38:7–13', fact: 'He used old rags under the ropes so Jeremiah would not be hurt.' },
  { cat: 'ot', level: 4, q: 'Who was the scribe who wrote down Jeremiah’s words?', answer: 'Baruch', wrong: ['Shaphan', 'Ezra', 'Seraiah'], ref: 'Jeremiah 36:4', fact: 'When the king burned the scroll, they wrote it all again.' },
  { cat: 'ot', level: 4, q: 'What Babylonian name was Daniel given?', answer: 'Belteshazzar', wrong: ['Belshazzar', 'Abednego', 'Shadrach'], ref: 'Daniel 1:7', fact: 'His friends Hananiah, Mishael and Azariah became Shadrach, Meshach and Abednego.' },
  { cat: 'ot', level: 4, q: 'In how many days were the walls of Jerusalem rebuilt under Nehemiah?', answer: '52', wrong: ['40', '70', '120'], ref: 'Nehemiah 6:15', fact: 'Even their enemies saw that the work was done by God.' },
  { cat: 'ot', level: 4, q: 'Which of these was one of Job’s three friends?', answer: 'Eliphaz', wrong: ['Eliakim', 'Elkanah', 'Eliezer'], ref: 'Job 2:11', fact: 'The other two were Bildad and Zophar.' },
  { cat: 'ot', level: 4, q: 'Before he was a prophet, what was Amos?', answer: 'A herdman from Tekoa', wrong: ['A priest at Bethel', 'A scribe in the palace', 'A soldier in the army'], ref: 'Amos 1:1; 7:14', fact: 'He also gathered sycamore fruit.' },
  { cat: 'ot', level: 4, q: 'Which prophet foretold the king coming “lowly, and riding upon an ass”?', answer: 'Zechariah', wrong: ['Haggai', 'Malachi', 'Nahum'], ref: 'Zechariah 9:9', fact: 'Matthew 21 shows Jesus fulfilling it on Palm Sunday.' },
  { cat: 'ot', level: 4, q: 'Which prophet wrote, “the just shall live by his faith”?', answer: 'Habakkuk', wrong: ['Obadiah', 'Zephaniah', 'Joel'], ref: 'Habakkuk 2:4', fact: 'Paul quotes it in Romans 1:17 and Galatians 3:11.' },
  { cat: 'ot', level: 4, q: 'Which prophet foretold, “I will pour out my spirit upon all flesh”?', answer: 'Joel', wrong: ['Amos', 'Micah', 'Ezekiel'], ref: 'Joel 2:28', fact: 'Peter said Pentecost was this promise coming true (Acts 2:16–17).' },
  { cat: 'ot', level: 4, q: 'Every how many years was the Year of Jubilee?', answer: '50', wrong: ['7', '25', '70'], ref: 'Leviticus 25:10–11', fact: 'Land went back to its families and liberty was proclaimed.' },
  { cat: 'ot', level: 4, q: 'How many cities of refuge were set apart in Israel?', answer: 'Six', wrong: ['Three', 'Twelve', 'Forty-eight'], ref: 'Numbers 35:13–14', fact: 'Three were on each side of the Jordan.' },
  { cat: 'ot', level: 4, q: 'Whose five daughters asked Moses for their father’s inheritance?', answer: 'Zelophehad', wrong: ['Korah', 'Caleb', 'Jair'], ref: 'Numbers 27:1–7', fact: 'God said, “The daughters of Zelophehad speak right.”' },
  { cat: 'ot', level: 4, q: 'From which mountain did Moses view the Promised Land before he died?', answer: 'Mount Nebo', wrong: ['Mount Hor', 'Mount Gerizim', 'Mount Tabor'], ref: 'Deuteronomy 34:1', fact: 'Aaron had died on Mount Hor.' },
  { cat: 'ot', level: 4, q: 'Whose rebellion ended when the ground opened and swallowed the rebels?', answer: 'Korah’s', wrong: ['Achan’s', 'Absalom’s', 'Sheba’s'], ref: 'Numbers 16:31–32', fact: 'Korah’s own sons did not die (Numbers 26:11); several psalms are titled for the sons of Korah.' },
  { cat: 'ot', level: 4, q: 'Which king of Salem was also priest of the most high God and blessed Abram?', answer: 'Melchizedek', wrong: ['Abimelech', 'Hiram', 'Chedorlaomer'], ref: 'Genesis 14:18–19', fact: 'Hebrews calls Jesus a priest for ever after the order of Melchizedek.' },
  { cat: 'ot', level: 4, q: 'Which of Jacob’s sons offered to stay as a slave instead of Benjamin?', answer: 'Judah', wrong: ['Reuben', 'Simeon', 'Levi'], ref: 'Genesis 44:33', fact: 'Jesus came from the tribe of Judah.' },
  { cat: 'ot', level: 4, q: 'What did Samuel name the stone he set up, saying “Hitherto hath the LORD helped us”?', answer: 'Ebenezer', wrong: ['Bethel', 'Gilgal', 'Mizpah'], ref: '1 Samuel 7:12', fact: 'Ebenezer means “stone of help”.' },
  { cat: 'ot', level: 4, q: 'Which baby was named to mean “the glory is departed from Israel”?', answer: 'Ichabod', wrong: ['Ishbosheth', 'Ishmael', 'Jabez'], ref: '1 Samuel 4:21', fact: 'He was born the day the ark of God was captured.' },
  { cat: 'ot', level: 4, q: 'Which man in a family list prayed “Oh that thou wouldest bless me indeed”?', answer: 'Jabez', wrong: ['Jehu', 'Jethro', 'Jashobeam'], ref: '1 Chronicles 4:10', fact: 'God granted him that which he requested.' },
  { cat: 'ot', level: 4, q: 'Which prophet’s book is a vision about the nation of Edom?', answer: 'Obadiah', wrong: ['Nahum', 'Zephaniah', 'Haggai'], ref: 'Obadiah 1:1', fact: 'It is the shortest book in the Old Testament.' },
  { cat: 'ot', level: 4, q: 'Which prophet’s book is about the coming fall of Nineveh?', answer: 'Nahum', wrong: ['Jonah', 'Joel', 'Habakkuk'], ref: 'Nahum 1:1', fact: 'Nineveh had repented in Jonah’s day but turned back to evil.' },
  { cat: 'ot', level: 4, q: 'Which prophet urged the returned exiles to finish rebuilding the temple, asking if it was time to live in panelled houses?', answer: 'Haggai', wrong: ['Malachi', 'Ezra', 'Daniel'], ref: 'Haggai 1:4', fact: 'Zechariah encouraged the same work at the same time.' },
  { cat: 'ot', level: 2, q: 'What was the name of Abraham’s nephew who chose the plain of Jordan?', answer: 'Lot', wrong: ['Nahor', 'Laban', 'Bethuel'], ref: 'Genesis 13:10–11', fact: 'Abraham let Lot choose first, trusting God with the rest.' },
  { cat: 'ot', level: 4, q: 'Who were Leah’s and Rachel’s maids, who also bore sons to Jacob?', answer: 'Zilpah and Bilhah', wrong: ['Shiphrah and Puah', 'Adah and Zillah', 'Hagar and Keturah'], ref: 'Genesis 30:3–10', fact: 'Bilhah was Rachel’s maid, and Zilpah was Leah’s.' },
  { cat: 'ot', level: 4, q: 'Which firstborn son of Jacob lost his birthright?', answer: 'Reuben', wrong: ['Judah', 'Simeon', 'Dan'], ref: '1 Chronicles 5:1', fact: 'The birthright was given to the sons of Joseph.' },

  { cat: 'nt', level: 4, q: 'With whom does Matthew’s list of Jesus’ ancestors begin?', answer: 'Abraham', wrong: ['Adam', 'David', 'Noah'], ref: 'Matthew 1:1–2', fact: 'Luke traces the line all the way back to Adam (Luke 3:38).' },
  { cat: 'nt', level: 4, q: 'Which elderly prophetess from the tribe of Aser gave thanks when she saw baby Jesus?', answer: 'Anna', wrong: ['Elizabeth', 'Hannah', 'Huldah'], ref: 'Luke 2:36–38', fact: 'She served God in the temple night and day.' },
  { cat: 'nt', level: 4, q: 'How many stone waterpots did Jesus have filled at the wedding in Cana?', answer: 'Six', wrong: ['Three', 'Seven', 'Twelve'], ref: 'John 2:6–7', fact: 'They filled them up to the brim.' },
  { cat: 'nt', level: 4, q: 'How long had the man at the pool of Bethesda been ill?', answer: '38 years', wrong: ['12 years', '18 years', '40 years'], ref: 'John 5:5–9', fact: 'Jesus said, “Rise, take up thy bed, and walk.”' },
  { cat: 'nt', level: 4, q: 'What words did Jesus say to Jairus’ daughter, meaning “Damsel, I say unto thee, arise”?', answer: 'Talitha cumi', wrong: ['Ephphatha', 'Eloi, Eloi', 'Maranatha'], ref: 'Mark 5:41', fact: 'Ephphatha, meaning “Be opened”, was said to a deaf man.' },
  { cat: 'nt', level: 4, q: 'What nickname did Jesus give James and John?', answer: 'Boanerges, sons of thunder', wrong: ['Didymus, the twins', 'Cephas, the stones', 'Zealots, the eager ones'], ref: 'Mark 3:17', fact: 'They once wanted to call fire down on a Samaritan village.' },
  { cat: 'nt', level: 4, q: 'How many large fish were caught when the risen Jesus told the disciples where to cast the net?', answer: '153', wrong: ['99', '144', '200'], ref: 'John 21:11', fact: 'Even with so many, the net was not broken.' },
  { cat: 'nt', level: 4, q: 'How many loaves did Jesus use to feed the four thousand?', answer: 'Seven', wrong: ['Five', 'Three', 'Twelve'], ref: 'Matthew 15:34–38', fact: 'Seven baskets of leftovers were taken up.' },
  { cat: 'nt', level: 4, q: 'What costly ointment did Mary of Bethany pour on Jesus’ feet?', answer: 'Spikenard', wrong: ['Myrrh', 'Frankincense', 'Olive oil'], ref: 'John 12:3', fact: 'The whole house was filled with the smell of it.' },
  { cat: 'nt', level: 4, q: 'What was the field bought with Judas’ money called?', answer: 'Aceldama, the field of blood', wrong: ['Gabbatha, the pavement', 'Golgotha, the skull', 'Bethesda, the house of mercy'], ref: 'Acts 1:19', fact: 'Matthew says the priests bought a potter’s field to bury strangers in.' },
  { cat: 'nt', level: 4, q: 'In which three languages was the sign over Jesus’ cross written?', answer: 'Hebrew, Greek and Latin', wrong: ['Hebrew, Aramaic and Egyptian', 'Greek, Latin and Persian', 'Hebrew, Greek and Arabic'], ref: 'John 19:20', fact: 'It read, “JESUS OF NAZARETH THE KING OF THE JEWS.”' },
  { cat: 'nt', level: 4, q: 'What was the name of one of the two disciples on the road to Emmaus?', answer: 'Cleopas', wrong: ['Clement', 'Crispus', 'Cornelius'], ref: 'Luke 24:18', fact: 'Their hearts burned as Jesus explained the Scriptures.' },
  { cat: 'nt', level: 4, q: 'Which girl was so happy to hear Peter at the door that she forgot to open it?', answer: 'Rhoda', wrong: ['Dorcas', 'Lydia', 'Phoebe'], ref: 'Acts 12:13–14', fact: 'The church had been praying for Peter, but did not believe it was him!' },
  { cat: 'nt', level: 4, q: 'What does the name Barnabas mean?', answer: 'Son of consolation', wrong: ['Son of thunder', 'Son of the law', 'Son of peace'], ref: 'Acts 4:36', fact: 'His real name was Joses, a Levite from Cyprus.' },
  { cat: 'nt', level: 4, q: 'Who left Paul and Barnabas partway through their first journey?', answer: 'John Mark', wrong: ['Silas', 'Titus', 'Luke'], ref: 'Acts 13:13', fact: 'Years later Paul wrote that Mark was profitable to him (2 Timothy 4:11).' },
  { cat: 'nt', level: 4, q: 'What did the people of Lystra call Barnabas and Paul after a healing?', answer: 'Jupiter and Mercurius', wrong: ['Apollo and Mars', 'Saturn and Neptune', 'Castor and Pollux'], ref: 'Acts 14:12', fact: 'Paul and Barnabas tore their clothes and pointed them to the living God.' },
  { cat: 'nt', level: 4, q: 'Which king said to Paul, “Almost thou persuadest me to be a Christian”?', answer: 'Agrippa', wrong: ['Felix', 'Festus', 'Herod Antipas'], ref: 'Acts 26:28', fact: 'Paul wished that everyone listening would become like him, apart from his chains.' },
  { cat: 'nt', level: 4, q: 'Who were Timothy’s mother and grandmother?', answer: 'Eunice and Lois', wrong: ['Lydia and Chloe', 'Priscilla and Phoebe', 'Mary and Salome'], ref: '2 Timothy 1:5', fact: 'Their sincere faith was passed down to Timothy.' },
  { cat: 'nt', level: 4, q: 'Which sorcerer in Samaria tried to buy the power of the Holy Spirit?', answer: 'Simon', wrong: ['Elymas', 'Bar-jesus', 'Sceva'], ref: 'Acts 8:18–20', fact: 'Peter told him the gift of God cannot be bought with money.' },
  { cat: 'nt', level: 4, q: 'Which sorcerer on Cyprus was struck blind for opposing Paul?', answer: 'Elymas', wrong: ['Simon', 'Demetrius', 'Alexander'], ref: 'Acts 13:8–11', fact: 'The governor, Sergius Paulus, believed.' },
  { cat: 'nt', level: 4, q: 'Which silversmith in Ephesus stirred up a riot against Paul?', answer: 'Demetrius', wrong: ['Alexander', 'Erastus', 'Tyrannus'], ref: 'Acts 19:24–29', fact: 'He made silver shrines for the goddess Diana and feared losing business.' },
  { cat: 'nt', level: 4, q: 'What was the name of the chief man of Malta whose father Paul healed?', answer: 'Publius', wrong: ['Julius', 'Sergius', 'Lysias'], ref: 'Acts 28:7–8', fact: 'Afterwards others on the island came and were healed too.' },
  { cat: 'nt', level: 4, q: 'Which church in Revelation was told it had left its first love?', answer: 'Ephesus', wrong: ['Laodicea', 'Pergamos', 'Thyatira'], ref: 'Revelation 2:1–4', fact: 'Jesus called them to remember and return.' },
  { cat: 'nt', level: 4, q: 'Which Old Testament prophet did Jesus say was the sign given to that generation?', answer: 'Jonas (Jonah)', wrong: ['Elias (Elijah)', 'Esaias (Isaiah)', 'Daniel'], ref: 'Matthew 12:39–40', fact: 'As Jonah was three days in the fish, Jesus would be three days in the earth.' },
  { cat: 'nt', level: 4, q: 'Where was Jesus when a woman said, “Sir, give me this water, that I thirst not”?', answer: 'Sychar in Samaria', wrong: ['Bethany', 'Nain', 'Cana'], ref: 'John 4:5, 15', fact: 'Jesus told her he was the Messiah.' },
  { cat: 'nt', level: 4, q: 'In which town did Jesus raise a widow’s only son during his funeral?', answer: 'Nain', wrong: ['Cana', 'Bethany', 'Bethsaida'], ref: 'Luke 7:11–15', fact: 'Jesus had compassion on her and said, “Weep not.”' },
  { cat: 'nt', level: 4, q: 'Which ruler died, eaten of worms, after accepting praise as a god?', answer: 'Herod', wrong: ['Pilate', 'Felix', 'Festus'], ref: 'Acts 12:21–23', fact: 'The very next verse says the word of God grew and multiplied.' },
  { cat: 'nt', level: 4, q: 'Which deacon was a proselyte from Antioch?', answer: 'Nicolas', wrong: ['Stephen', 'Philip', 'Prochorus'], ref: 'Acts 6:5', fact: 'Stephen and Philip were also among the seven chosen.' },
  { cat: 'nt', level: 4, q: 'Which of Paul’s letters mentions women named Euodias and Syntyche?', answer: 'Philippians', wrong: ['Colossians', 'Romans', 'Titus'], ref: 'Philippians 4:2', fact: 'Paul urged them to be of the same mind in the Lord.' },
  { cat: 'nt', level: 4, q: 'Which servant of the church at Cenchrea did Paul commend in Romans 16?', answer: 'Phoebe', wrong: ['Priscilla', 'Chloe', 'Junia'], ref: 'Romans 16:1', fact: 'He asked the church to help her in whatever she needed.' },
  { cat: 'nt', level: 4, q: 'In the parable, what was the name of the beggar who lay at the rich man’s gate?', answer: 'Lazarus', wrong: ['Bartimaeus', 'Malchus', 'Simon'], ref: 'Luke 16:20', fact: 'Abraham said, “They have Moses and the prophets; let them hear them.”' },
  { cat: 'nt', level: 4, q: 'Which psalm did Jesus quote on the cross with “My God, my God, why hast thou forsaken me?”', answer: 'Psalm 22', wrong: ['Psalm 23', 'Psalm 51', 'Psalm 91'], ref: 'Matthew 27:46; Psalm 22:1', fact: 'The same psalm speaks of pierced hands and feet and casting lots for clothing.' },
  { cat: 'nt', level: 4, q: 'Who warned the chief captain about a plot by forty men to kill Paul?', answer: 'Paul’s sister’s son', wrong: ['Barnabas', 'Silas', 'Timothy'], ref: 'Acts 23:16–22', fact: 'The men had vowed not to eat or drink until they had killed Paul.' },
  { cat: 'nt', level: 4, q: 'Which city’s believers did Paul praise as an example to all in Macedonia and Achaia?', answer: 'Thessalonica', wrong: ['Corinth', 'Ephesus', 'Rome'], ref: '1 Thessalonians 1:7', fact: 'They had turned from idols to serve the living and true God.' },
  { cat: 'nt', level: 4, q: 'Which disciple was a native of Cana in Galilee?', answer: 'Nathanael', wrong: ['Philip', 'Andrew', 'Matthew'], ref: 'John 21:2', fact: 'Jesus called him “an Israelite indeed, in whom is no guile”.' },
  { cat: 'nt', level: 4, q: 'From which town did Philip, Andrew and Peter come?', answer: 'Bethsaida', wrong: ['Capernaum', 'Nazareth', 'Magdala'], ref: 'John 1:44', fact: 'Jesus later did many mighty works there (Matthew 11:21).' },
  { cat: 'nt', level: 4, q: 'Who was high priest before Caiaphas and questioned Jesus first?', answer: 'Annas', wrong: ['Ananias', 'Eli', 'Gamaliel'], ref: 'John 18:13', fact: 'Annas was Caiaphas’ father-in-law.' },
  { cat: 'nt', level: 4, q: 'Where was Pilate’s judgment seat, called Gabbatha in Hebrew?', answer: 'The Pavement', wrong: ['The Porch', 'The Treasury', 'The Gate'], ref: 'John 19:13', fact: 'There Pilate said, “Behold your King!”' },
  { cat: 'nt', level: 4, q: 'Which seven-sons family of exorcists was beaten by an evil spirit in Ephesus?', answer: 'The sons of Sceva', wrong: ['The sons of Zebedee', 'The sons of Alphaeus', 'The sons of Korah'], ref: 'Acts 19:14–16', fact: 'The spirit said, “Jesus I know, and Paul I know; but who are ye?”' },

  { cat: 'gen', level: 4, q: 'Besides Hebrew, which language is used in parts of Daniel and Ezra?', answer: 'Aramaic', wrong: ['Greek', 'Latin', 'Persian'], ref: 'Daniel 2:4; Ezra 4:8', fact: 'Jesus also spoke Aramaic words like “Abba” and “Talitha cumi”.' },
  { cat: 'gen', level: 4, q: 'Which three Gospels are called the Synoptic Gospels?', answer: 'Matthew, Mark and Luke', wrong: ['Mark, Luke and John', 'Matthew, Luke and John', 'Matthew, Mark and John'], ref: 'Matthew, Mark, Luke', fact: '“Synoptic” means they “see together”, telling many of the same events.' },
  { cat: 'gen', level: 4, q: 'Which is the shortest chapter in the Bible?', answer: 'Psalm 117', wrong: ['Psalm 23', 'John 11', 'Jude 1'], ref: 'Psalm 117', fact: 'It has just two verses calling all nations to praise the Lord.' },
  { cat: 'gen', level: 4, q: 'Which psalm says, “Be still, and know that I am God”?', answer: 'Psalm 46', wrong: ['Psalm 23', 'Psalm 91', 'Psalm 121'], ref: 'Psalm 46:10', fact: 'It begins, “God is our refuge and strength, a very present help in trouble.”' },
  { cat: 'gen', level: 4, q: 'Which psalm begins, “I will lift up mine eyes unto the hills”?', answer: 'Psalm 121', wrong: ['Psalm 1', 'Psalm 46', 'Psalm 139'], ref: 'Psalm 121:1', fact: 'It answers, “My help cometh from the LORD, which made heaven and earth.”' },
  { cat: 'gen', level: 4, q: 'Which psalm is a prayer of David after Nathan confronted him?', answer: 'Psalm 51', wrong: ['Psalm 23', 'Psalm 32', 'Psalm 90'], ref: 'Psalm 51:10', fact: 'David prayed, “Create in me a clean heart, O God.”' },
  { cat: 'gen', level: 4, q: 'Which psalm is titled “A Prayer of Moses the man of God”?', answer: 'Psalm 90', wrong: ['Psalm 1', 'Psalm 50', 'Psalm 119'], ref: 'Psalm 90', fact: 'It asks God to “teach us to number our days”.' },
  { cat: 'gen', level: 4, q: 'Which book has the Hebrew alphabet acrostic poem about a virtuous woman?', answer: 'Proverbs', wrong: ['Ruth', 'Song of Solomon', 'Ecclesiastes'], ref: 'Proverbs 31:10', fact: '“Who can find a virtuous woman? for her price is far above rubies.”' },
  { cat: 'gen', level: 4, q: 'What is the name for the letters 1 and 2 Timothy and Titus?', answer: 'The Pastoral Epistles', wrong: ['The Prison Epistles', 'The General Epistles', 'The Wisdom Books'], ref: '1 Timothy 1:2; Titus 1:4', fact: 'Paul wrote them to guide leaders caring for churches.' },
  { cat: 'gen', level: 4, q: 'How many chapters does the book of Isaiah have?', answer: '66', wrong: ['50', '52', '150'], ref: 'Isaiah', fact: 'The same number as the books in most Protestant Bibles.' },
  { cat: 'gen', level: 4, q: 'How many chapters are in the book of Revelation?', answer: '22', wrong: ['21', '28', '16'], ref: 'Revelation 22:21', fact: 'The last verse is a blessing of the grace of our Lord Jesus Christ.' },
  { cat: 'gen', level: 4, q: 'Which New Testament letter is addressed “to the twelve tribes which are scattered abroad”?', answer: 'James', wrong: ['Hebrews', '1 Peter', 'Jude'], ref: 'James 1:1', fact: 'James calls himself a servant of God and of the Lord Jesus Christ.' },
  { cat: 'gen', level: 4, q: 'Which book of the Bible ends with the words “Amen. Even so, come, Lord Jesus”, then a grace?', answer: 'Revelation', wrong: ['Jude', 'Malachi', '2 Peter'], ref: 'Revelation 22:20–21', fact: 'The Bible ends with a longing for Jesus’ return.' },
  { cat: 'gen', level: 4, q: 'Which prophet asked, “what doth the LORD require of thee”?', answer: 'Micah', wrong: ['Amos', 'Joel', 'Hosea'], ref: 'Micah 6:8', fact: 'The answer: to do justly, to love mercy, and to walk humbly with thy God.' },
  { cat: 'gen', level: 4, q: 'Which book says, “Where there is no vision, the people perish”?', answer: 'Proverbs', wrong: ['Habakkuk', 'Ecclesiastes', 'Daniel'], ref: 'Proverbs 29:18', fact: 'It goes on, “but he that keepeth the law, happy is he.”' },

  // ---------- Extra mix ----------
  { cat: 'ot', level: 1, q: 'What did God make on the fourth day?', answer: 'The sun, moon and stars', wrong: ['The fish and birds', 'The dry land', 'People'], ref: 'Genesis 1:16–19', fact: 'The greater light ruled the day and the lesser light the night.' },
  { cat: 'ot', level: 1, q: 'Which special tree stood in the middle of Eden with the tree of knowledge?', answer: 'The tree of life', wrong: ['The olive tree', 'The fig tree', 'The cedar of Lebanon'], ref: 'Genesis 2:9', fact: 'In Revelation 22 the tree of life appears again for God’s people.' },
  { cat: 'ot', level: 1, q: 'What did Moses’ staff turn into in front of Pharaoh?', answer: 'A snake', wrong: ['A tree', 'A sword', 'A dove'], ref: 'Exodus 7:10', fact: 'Aaron’s rod swallowed up the magicians’ rods.' },
  { cat: 'ot', level: 1, q: 'What did the Israelites carry that held the tablets of the law?', answer: 'The ark of the covenant', wrong: ['A golden basket', 'A clay jar', 'A leather bag'], ref: 'Deuteronomy 10:5', fact: 'It was a wooden chest covered with gold.' },
  { cat: 'ot', level: 1, q: 'How many days did Israel march around Jericho?', answer: 'Seven', wrong: ['Three', 'Ten', 'Forty'], ref: 'Joshua 6:14–15', fact: 'On the seventh day they went round seven times.' },
  { cat: 'ot', level: 1, q: 'Who was Ruth’s second husband, a kind farmer?', answer: 'Boaz', wrong: ['Jesse', 'Elimelech', 'Gideon'], ref: 'Ruth 4:13', fact: 'Boaz redeemed Ruth, a picture of how Jesus redeems us.' },
  { cat: 'ot', level: 1, q: 'What did God make on the third day?', answer: 'Dry land and plants', wrong: ['The sun and moon', 'Birds and fish', 'People'], ref: 'Genesis 1:9–13', fact: 'God saw that it was good.' },
  { cat: 'ot', level: 1, q: 'How many sons did Jacob have?', answer: 'Twelve', wrong: ['Seven', 'Ten', 'Two'], ref: 'Genesis 35:22', fact: 'Their families became the twelve tribes of Israel.' },
  { cat: 'ot', level: 1, q: 'Which animal did Samson tear apart with his bare hands?', answer: 'A lion', wrong: ['A bear', 'A wolf', 'A bull'], ref: 'Judges 14:5–6', fact: 'The Spirit of the Lord came mightily upon him.' },
  { cat: 'ot', level: 1, q: 'Who was the father of Isaac?', answer: 'Abraham', wrong: ['Jacob', 'Noah', 'Lot'], ref: 'Genesis 21:3', fact: 'Abraham is called the father of all who believe (Romans 4:11).' },
  { cat: 'nt', level: 1, q: 'What did Jesus do for the man who was let down through the roof?', answer: 'Forgave his sins and healed him', wrong: ['Gave him money', 'Sent him to the priest', 'Told him to wait'], ref: 'Mark 2:5, 11–12', fact: 'The man picked up his bed and walked out in front of everyone.' },
  { cat: 'nt', level: 1, q: 'What did Jesus do for the blind man who called out to him?', answer: 'He gave him his sight', wrong: ['He gave him a coat', 'He sent him away', 'He gave him bread'], ref: 'Mark 10:51–52', fact: 'The man followed Jesus along the road.' },
  { cat: 'nt', level: 1, q: 'Who visited baby Jesus on the night he was born?', answer: 'Shepherds', wrong: ['Roman soldiers', 'King Herod', 'The high priest'], ref: 'Luke 2:15–16', fact: 'Afterwards they told everyone what they had seen.' },
  { cat: 'nt', level: 1, q: 'Which king tried to kill baby Jesus?', answer: 'Herod', wrong: ['Pilate', 'Caesar Augustus', 'David'], ref: 'Matthew 2:13, 16', fact: 'God warned Joseph in a dream to flee to safety.' },
  { cat: 'nt', level: 1, q: 'What did Jesus say we should do for our enemies?', answer: 'Love them and pray for them', wrong: ['Avoid them forever', 'Pay them back', 'Ignore them'], ref: 'Matthew 5:44', fact: 'That is how God treats us.' },
  { cat: 'nt', level: 1, q: 'What did the Holy Spirit look like when it came down on Jesus at his baptism?', answer: 'A dove', wrong: ['A flame', 'An eagle', 'A cloud'], ref: 'Luke 3:22', fact: 'God said, “Thou art my beloved Son; in thee I am well pleased.”' },
  { cat: 'nt', level: 1, q: 'What did the disciples see on the heads of believers at Pentecost?', answer: 'Tongues like fire', wrong: ['Crowns of gold', 'Rainbows', 'Doves'], ref: 'Acts 2:3', fact: 'There was also a sound like a rushing mighty wind.' },
  { cat: 'nt', level: 1, q: 'What did Jesus say is more blessed than receiving?', answer: 'Giving', wrong: ['Praying', 'Fasting', 'Singing'], ref: 'Acts 20:35', fact: 'Paul reminded the Ephesian leaders of these words of Jesus.' },
  { cat: 'gen', level: 1, q: 'Which book of the Bible tells the story of Ruth and Boaz?', answer: 'Ruth', wrong: ['Esther', 'Judges', 'Genesis'], ref: 'Ruth 2', fact: 'It is only four chapters long.' },
  { cat: 'gen', level: 1, q: 'Which book tells how Israel escaped from Egypt?', answer: 'Exodus', wrong: ['Genesis', 'Numbers', 'Joshua'], ref: 'Exodus 12:41', fact: 'They left after 430 years.' },
  { cat: 'gen', level: 1, q: 'Which Gospel is the second book of the New Testament?', answer: 'Mark', wrong: ['Luke', 'John', 'Acts'], ref: 'Mark 1:1', fact: 'Mark is fast-paced and often says “straightway”.' },

  { cat: 'ot', level: 2, q: 'How did Elijah’s challenge on Mount Carmel test the prophets of Baal?', answer: 'Which god would answer by fire', wrong: ['Which god would send rain first', 'Who could build the tallest altar', 'Who could fast the longest'], ref: '1 Kings 18:24', fact: 'Baal never answered; the Lord did, at once.' },
  { cat: 'ot', level: 2, q: 'Who said, “As for me and my house, we will serve the LORD”?', answer: 'Joshua', wrong: ['Moses', 'David', 'Samuel'], ref: 'Joshua 24:15', fact: 'He told the people to choose that day whom they would serve.' },
  { cat: 'ot', level: 2, q: 'What did the people of Israel complain about before God sent quails?', answer: 'They wanted meat', wrong: ['They wanted gold', 'They wanted a king', 'They wanted rain'], ref: 'Exodus 16:3, 13', fact: 'God provided again, even for grumblers.' },
  { cat: 'ot', level: 2, q: 'Finish Joseph’s words: “Ye thought evil against me; but God meant it unto ...”', answer: 'good', wrong: ['harm', 'judgment', 'a lesson'], ref: 'Genesis 50:20', fact: 'God can bring good out of what others meant for harm, as he did at the cross.' },
  { cat: 'nt', level: 2, q: 'At what age did Jesus begin his public ministry, according to Luke?', answer: 'About thirty', wrong: ['About twenty', 'About forty', 'Twelve'], ref: 'Luke 3:23', fact: 'Luke then traces his family line.' },
  { cat: 'nt', level: 2, q: 'Who did Jesus say was the greatest in the kingdom of heaven?', answer: 'Whoever humbles himself like a little child', wrong: ['Whoever gives the most money', 'Whoever knows the most Scripture', 'Whoever leads the most people'], ref: 'Matthew 18:4', fact: 'Jesus set a child in the middle of them to show them.' },
  { cat: 'nt', level: 2, q: 'How many times did Jesus tell Peter to forgive?', answer: 'Seventy times seven', wrong: ['Seven times', 'Three times', 'Twelve times'], ref: 'Matthew 18:21–22', fact: 'In other words: keep on forgiving.' },
  { cat: 'nt', level: 2, q: 'What was written about the poor widow who gave two mites?', answer: 'She gave more than all the rich', wrong: ['She gave too little', 'She should have kept it', 'She gave it to the wrong place'], ref: 'Mark 12:42–44', fact: 'She gave all that she had.' },
  { cat: 'gen', level: 2, q: 'Which letter calls your body “the temple of the Holy Ghost”?', answer: '1 Corinthians', wrong: ['Romans', 'Hebrews', 'James'], ref: '1 Corinthians 6:19', fact: 'Paul reminds us we were bought with a price.' },

  { cat: 'ot', level: 3, q: 'Which prophet was told to lie on his side for many days as a sign?', answer: 'Ezekiel', wrong: ['Jeremiah', 'Hosea', 'Jonah'], ref: 'Ezekiel 4:4–6', fact: 'Ezekiel acted out many messages for the exiles.' },
  { cat: 'ot', level: 3, q: 'What did King Belshazzar’s guests drink from at his feast?', answer: 'Gold and silver vessels from the temple', wrong: ['Cups made of pearl', 'Clay jars from Egypt', 'Horns of oxen'], ref: 'Daniel 5:2–3', fact: 'That same night the writing appeared on the wall.' },
  { cat: 'nt', level: 3, q: 'Which disciple asked Jesus, “Lord, shew us the Father”?', answer: 'Philip', wrong: ['Thomas', 'Peter', 'Andrew'], ref: 'John 14:8–9', fact: 'Jesus answered, “He that hath seen me hath seen the Father.”' },
  { cat: 'nt', level: 3, q: 'Which disciple was nicknamed the Zealot?', answer: 'Simon', wrong: ['Jude', 'James', 'Philip'], ref: 'Luke 6:15', fact: 'Jesus chose people from very different backgrounds.' },
  { cat: 'gen', level: 3, q: 'Which Old Testament book is quoted by Jesus in reply to every one of the devil’s temptations?', answer: 'Deuteronomy', wrong: ['Isaiah', 'Psalms', 'Genesis'], ref: 'Matthew 4:4, 7, 10', fact: '“Man shall not live by bread alone” is from Deuteronomy 8:3.' },

  { cat: 'ot', level: 4, q: 'What was the name of David’s eldest brother?', answer: 'Eliab', wrong: ['Abinadab', 'Shammah', 'Joab'], ref: '1 Samuel 17:13, 28', fact: 'Eliab scolded David for coming to see the battle.' },
  { cat: 'ot', level: 4, q: 'Which prophetess did King Josiah’s officials consult about the book of the law?', answer: 'Huldah', wrong: ['Deborah', 'Miriam', 'Noadiah'], ref: '2 Kings 22:14', fact: 'She said judgment would come, but not in Josiah’s days.' },
  { cat: 'ot', level: 4, q: 'Which king of Moab was so fat that Ehud’s dagger disappeared into him?', answer: 'Eglon', wrong: ['Balak', 'Mesha', 'Agag'], ref: 'Judges 3:17, 22', fact: 'God raised Ehud up as a deliverer.' },
  { cat: 'ot', level: 4, q: 'Who was Ruth’s first husband?', answer: 'Mahlon', wrong: ['Chilion', 'Elimelech', 'Obed'], ref: 'Ruth 4:10', fact: 'Chilion had married Orpah.' },
  { cat: 'ot', level: 4, q: 'What was the name of Abraham’s wife after Sarah died?', answer: 'Keturah', wrong: ['Hagar', 'Milcah', 'Bilhah'], ref: 'Genesis 25:1', fact: 'She bore Abraham six more sons.' },
  { cat: 'nt', level: 4, q: 'Which governor took over from Felix while Paul was in prison?', answer: 'Festus', wrong: ['Pilate', 'Gallio', 'Sergius Paulus'], ref: 'Acts 24:27', fact: 'Porcius Festus came into Felix’s place after two years.' },
  { cat: 'nt', level: 4, q: 'Which Roman proconsul of Achaia refused to judge Paul’s case?', answer: 'Gallio', wrong: ['Festus', 'Felix', 'Sergius Paulus'], ref: 'Acts 18:12–16', fact: 'He said it was a question of words and names, not crime.' },
  { cat: 'nt', level: 4, q: 'In whose school did Paul teach daily for two years at Ephesus?', answer: 'Tyrannus', wrong: ['Gamaliel', 'Theophilus', 'Erastus'], ref: 'Acts 19:9–10', fact: 'All Asia heard the word of the Lord Jesus.' },
  { cat: 'nt', level: 4, q: 'To whom are both the Gospel of Luke and Acts addressed?', answer: 'Theophilus', wrong: ['Timothy', 'Titus', 'Philemon'], ref: 'Luke 1:3; Acts 1:1', fact: 'Luke wrote so he might know the certainty of what he had been taught.' },
  { cat: 'gen', level: 4, q: 'Which book of the Bible contains the longest verse, about the king’s scribes and the provinces?', answer: 'Esther', wrong: ['Numbers', 'Daniel', 'Ezra'], ref: 'Esther 8:9', fact: 'It lists the provinces from India unto Ethiopia, 127 of them.' },
];
